/* AI in Motion — Mathematics for Machine Learning track (deep dives, 10+ minutes each). © Janin A Apurba, CSE, AUST */
const S = (kit, chapter, o, say) => Object.assign({ kit, chapter }, o, { say });

module.exports = [
  {
    slug: 'vectors-and-dot-products', title: 'Vectors, Norms and the Dot Product', track: 'math', level: 'Beginner', deep: true,
    summary: 'A deep dive into the object every model is built from: what vectors are, how to add, scale and measure them, and why the dot product powers neurons, attention and semantic search.',
    scenes: [
      S('title', 'Introduction', { title: 'Vectors, Norms and the Dot Product', sub: 'The language every machine learning model speaks', track: 'Mathematics for ML' }, 'Welcome to this deep dive on vectors. Every input a model sees, every word embedding, every image and every set of learned weights is stored as a vector. Once you understand vectors and the dot product, most of the mathematics behind modern AI starts to make sense.'),
      S('definition', 'What is a vector?', { term: 'Vector', def: 'An ordered list of numbers. Picture it as a point in space, or as an arrow from the origin to that point.', eg: 'a customer = [age, height, income] = [34, 172, 5200]' }, 'So what exactly is a vector? At its simplest it is an ordered list of numbers. You can picture it as a point in space, or as an arrow from the origin to that point. A customer described by age, height and income is a vector with three numbers.'),
      S('stats', 'Vectors everywhere', { head: 'Vectors in real AI systems', items: [['3', 'numbers', 'one RGB colour'], ['784', 'pixels', 'a 28 × 28 handwritten digit'], ['768', 'numbers', 'one BERT-base word embedding'], ['12,288', 'numbers', 'one token inside GPT-3']] }, 'Vectors appear everywhere in AI. A colour is three numbers. A small handwritten digit image is seven hundred and eighty four pixel values. A BERT word embedding has seven hundred and sixty eight numbers, and each token inside GPT-3 flows through the network as a vector of twelve thousand, two hundred and eighty eight numbers.'),
      S('vectors', 'Basis vectors', { mode: 'basis', a: [3, 2] }, 'Coordinates are really instructions. The vector three, two means: take three steps along the first basis vector, called i hat, and then two steps along the second basis vector, j hat. Every vector is a combination of basis vectors, and its numbers tell you how much of each one to use.'),
      S('vectors', 'Adding vectors', { mode: 'add', a: [3, 1], b: [1, 2] }, 'Adding two vectors means adding them component by component. Geometrically, slide the tail of b to the tip of a, and the sum is the arrow from the start of a to the end of b. Here three, one plus one, two gives four, three. Order does not matter.'),
      S('vectors', 'Scaling vectors', { mode: 'scale', a: [2, 1], cs: [1, 2, -1, 0.5] }, 'Multiplying a vector by a single number, called a scalar, stretches or shrinks it. A factor of two doubles its length. A negative factor flips it to point the other way. A factor of one half shrinks it. The arrow always stays on the same line through the origin.'),
      S('equation', 'Linear combinations', { head: 'Linear combination', size: 50, parts: [{ t: 'w₁x₁', c: 'cyan', note: 'Scale the first vector (or number) by a weight' }, { t: ' + ' }, { t: 'w₂x₂', c: 'pink', note: 'Scale the second one by its weight' }, { t: ' + … + ' }, { t: 'wₙxₙ', c: 'amber', note: 'Add everything up: one weighted sum' }], below: 'The single most common computation in machine learning' }, 'Scaling and adding together give a linear combination: multiply each item by a weight and add them all up. This is the most common computation in machine learning. A neuron, a linear regression, an attention layer and a recommendation score all compute weighted sums of exactly this form.'),
      S('compare', 'Two views', { head: 'Two ways to see a vector', left: { title: 'An arrow (geometry)', items: ['Has a direction and a length', 'Gives intuition for angles and distance', 'Easy to draw in 2-D or 3-D'], color: 'cyan' }, right: { title: 'A list (algebra)', items: ['Components indexed 1 … n', 'Works in any number of dimensions', 'What GPUs actually store and crunch'], color: 'violet' } }, 'It helps to hold two views at the same time. Geometrically a vector is an arrow with a direction and a length, which gives intuition about angles and distances. Algebraically it is a list of numbers, which works in any number of dimensions and is what computers actually store.'),
      S('definition', 'Length: the norm', { term: 'Norm ‖v‖', kicker: 'Length of a vector', def: '‖v‖ = √(v₁² + v₂² + … + vₙ²) — Pythagoras, extended to any number of dimensions.', eg: '‖[3, 4]‖ = √(9 + 16) = 5' }, 'The length of a vector is called its norm. In two dimensions it is simply Pythagoras: the vector three, four has length five. In any number of dimensions, square every component, add the squares, and take the square root. This is the Euclidean norm, also called the L two norm.'),
      S('norms', 'Other norms', { v: [0.6, 0.8] }, 'But length can be measured in several ways. The L one norm adds absolute values, and its unit ball is a diamond. The L two norm gives the familiar circle. The L infinity norm keeps only the largest component, which gives a square. For the green vector they give one point four, one, and point eight.'),
      S('question', 'Pause and think', { q: 'Under which norm does the vector [3, 4] have a length of exactly 7?', hint: 'Try adding the absolute values.', a: 'The L1 norm: |3| + |4| = 7. The L2 norm gives 5 and the L∞ norm gives 4.' }, 'Pause and think. Under which norm does the vector three, four have a length of exactly seven? Try the three norms we just met. The answer is the L one norm, because three plus four is seven. The L two norm gives five, and the L infinity norm gives four.'),
      S('definition', 'Distance', { term: 'Distance', kicker: 'How far apart are two points?', def: 'The distance between a and b is the norm of their difference: d(a, b) = ‖a − b‖.', eg: 'k-nearest neighbours, k-means clustering and squared-error losses are all built on distances' }, 'Once we can measure length, we can measure distance: the distance between two points is simply the norm of their difference. That one idea powers k nearest neighbours, k means clustering and the squared error loss used to train regression models.'),
      S('knn', 'Distances in action', { k: 5 }, 'Here is distance in action. To classify the new point, k nearest neighbours measures its distance to every training example, picks the closest ones and lets them vote. The choice of norm changes which points count as neighbours, and therefore changes the prediction.'),
      S('vectors', 'The dot product', { mode: 'dot', a: [3, 1], b: [1, 2] }, 'Now the star of the show: the dot product. Multiply matching components and add: three times one plus one times two equals five. That single number measures how much the two vectors point the same way. The green bar shows the projection of b onto a.'),
      S('equation', 'Two formulas, one number', { head: 'The dot product, two ways', size: 52, parts: [{ t: 'a · b', c: 'cyan', note: 'Algebra: multiply matching components and add them' }, { t: ' = ' }, { t: '|a| |b|', c: 'pink', note: 'Geometry: the product of the two lengths…' }, { t: ' cos θ', c: 'amber', note: '…times the cosine of the angle between them' }], below: 'Σ aᵢbᵢ = |a| |b| cos θ — true in any number of dimensions' }, 'The same number has a geometric meaning: the dot product equals the length of a, times the length of b, times the cosine of the angle between them. So the algebraic recipe and the geometric picture always agree, whether you have two dimensions or twelve thousand.'),
      S('plot', 'The cosine curve', { head: 'cos θ: from aligned to opposite', x: [0, 3.1416], y: [-1.2, 1.2], xstep: 0.5, fns: [{ f: 'cos(x)', label: 'cos θ', lx: 2.6, dy: 30 }], points: [[0, 1, 'θ = 0°: cos = 1', 'green'], [1.5708, 0, '90°: cos = 0', 'amber'], [3.1416, -1, '180°: cos = −1', 'red']], xl: 'θ (radians)', note: 'Positive when vectors agree, zero when perpendicular, negative when they disagree.' }, 'The cosine does the interpretive work. When two vectors point the same way the angle is zero and the cosine is one. At ninety degrees the cosine is zero. When they point in opposite directions the angle is one hundred and eighty degrees and the cosine is minus one.'),
      S('vectors', 'Rotating b', { mode: 'dot', a: [3, 1], b: [1, 2], sweep: true }, 'Watch what happens as b rotates. While the angle is small, the dot product is large and positive. At exactly ninety degrees it becomes zero, and the vectors are called orthogonal. Beyond that it turns negative, because b now points partly against a.'),
      S('question', 'Pause and think', { q: 'Two non-zero vectors have a dot product of exactly 0. What does that tell you?', a: 'They are orthogonal (perpendicular): neither has any component in the other’s direction.' }, 'Time to pause and think. If the dot product of two non zero vectors is exactly zero, what does that tell you about them? Take a moment. The answer: they are orthogonal, perpendicular to each other, so neither one has any component along the other.'),
      S('definition', 'Cosine similarity', { term: 'Cosine similarity', def: 'cos θ = (a · b) / (‖a‖ ‖b‖) — the dot product with the lengths divided out, so only direction matters.', eg: '−1 = opposite · 0 = unrelated · 1 = same direction' }, 'Divide the dot product by both lengths and you get cosine similarity. It ignores length and keeps only direction, ranging from minus one for opposite, through zero for unrelated, up to one for exactly the same direction. Search engines and chatbots use it to compare meanings.'),
      S('vector-search', 'Semantic search', {}, 'Here is cosine similarity at work. Every document is turned into an embedding vector, and so is the question. The system retrieves the documents whose vectors point in the most similar direction. This is how semantic search, and retrieval augmented generation, find relevant text.'),
      S('embedding', 'Directions carry meaning', { mode: 'analogy' }, 'Directions can even carry meaning. In a word embedding space, the arrow from man to woman is roughly parallel to the arrow from king to queen. Adding and subtracting vectors lets a model reason by analogy, at least approximately, which surprised researchers when word2vec first showed it.'),
      S('neuron', 'A neuron is a dot product', {}, 'A single artificial neuron is a dot product in disguise. It multiplies each input by its weight, adds them up, adds a bias, and passes the result through an activation function. The weights define a direction, and the neuron responds most strongly to inputs that line up with it.'),
      S('equation', 'The neuron formula', { head: 'One neuron', size: 60, parts: [{ t: 'z', c: 'amber', note: 'The pre-activation: one number' }, { t: ' = ' }, { t: 'w · x', c: 'cyan', note: 'How well the input matches the weight pattern' }, { t: ' + ' }, { t: 'b', c: 'pink', note: 'The bias shifts the threshold' }], below: 'Stack many neurons side by side and you have a layer: a matrix times a vector' }, 'Written as a formula, z equals w dot x plus b. The dot product checks how well the input matches the pattern stored in the weights, and the bias shifts the threshold. Stack many neurons side by side and you get a whole layer, which is a matrix times a vector.'),
      S('classify-boundary', 'A linear classifier', { model: 'perceptron' }, 'Geometrically, the set of points where w dot x plus b equals zero is a straight line, or in higher dimensions a flat hyperplane, and the weight vector is perpendicular to it. Points on one side give positive values, points on the other side negative ones. That is a linear classifier.'),
      S('definition', 'Projection', { term: 'Projection', kicker: 'How much of b lies along a?', def: 'proj_a(b) = (a · b / a · a) a — take the dot product, divide by a · a, and scale a by that amount.', eg: 'least squares regression, PCA and Gram–Schmidt are all built on projections' }, 'Projection answers the question: how much of b lies along a? Take the dot product, divide by a dot a, and scale a by that amount. Projections power least squares regression, principal component analysis and the Gram Schmidt process for building orthonormal bases.'),
      S('definition', 'Orthonormal bases', { term: 'Orthonormal basis', def: 'Basis vectors that are mutually perpendicular and each of length 1. Coordinates are then just dot products.', eg: 'î = [1, 0] and ĵ = [0, 1] are orthonormal; so are the principal components found by PCA' }, 'A set of vectors that are mutually perpendicular and each have length one is called orthonormal. With such a basis, finding a coordinate is easy: just take the dot product with the basis vector. The principal components found by PCA form exactly this kind of basis.'),
      S('pca', 'PCA uses projections', {}, 'PCA is projection in action. It finds the direction along which the data varies the most, then projects every point onto that direction. Keeping only the top few directions compresses many dimensions into a few while losing as little information as possible.'),
      S('qkv', 'Attention is dot products', {}, 'Transformers are built from dot products too. Here attention scores each word for the query it. Every score is the query dotted with a key, divided by the square root of the dimension. A softmax turns the scores into weights, and animal receives the most attention.'),
      S('pipeline', 'Dot products in a transformer', { head: 'Where dot products hide in a language model', steps: ['Embed tokens', 'Query · key scores', 'Weighted sum of values', 'MLP layers', 'Logits'], desc: ['Each token becomes a vector: a row of the embedding matrix.', 'Attention compares every query with every key by dot products.', 'The output is a linear combination of value vectors.', 'Each layer is a matrix: thousands of dot products at once.', 'Each vocabulary word’s score is the final vector dotted with its output embedding.'] }, 'In a language model, dot products are everywhere. Attention compares queries with keys by dot products and mixes values with weighted sums. The MLP layers are matrix vector products. Even the final score for every word in the vocabulary is a dot product.'),
      S('code', 'In code', { head: 'Dot products in NumPy', file: 'vectors.py', lines: ['import numpy as np', '', 'a = np.array([3.0, 1.0])', 'b = np.array([1.0, 2.0])', '', 'dot = a @ b                    # 3*1 + 1*2 = 5.0', 'norm_a = np.linalg.norm(a)     # sqrt(10) ~ 3.162', 'cos = dot / (norm_a * np.linalg.norm(b))', 'print(dot, round(cos, 3))      # 5.0 0.707'], hl: [[2, 3], 5, [6, 7], 8], notes: ['Vectors are NumPy arrays', 'The @ operator computes the dot product', 'Norms give lengths; dividing gives cosine similarity', 'dot = 5 and cosine ≈ 0.707, so the angle is 45°'] }, 'In code this takes a few lines. NumPy arrays hold the vectors, the at operator computes the dot product, and the norm function gives lengths. For our example the dot product is five and the cosine similarity is about point seven one, which means an angle of forty five degrees.'),
      S('compare', 'Vectorise', { head: 'Loops versus vectorised maths', left: { title: 'Python loop', items: ['One multiply-add at a time', 'Interpreter overhead on every step', 'Painfully slow for big vectors'], color: 'red' }, right: { title: 'Vectorised (NumPy, GPU)', items: ['Whole arrays in one call', 'Runs in optimised C and CUDA', 'Often tens to hundreds of times faster'], color: 'green' } }, 'A practical lesson: never loop over vector components in Python. A vectorised call hands the whole array to optimised code written in C or running on a GPU, which is often tens to hundreds of times faster. Deep learning frameworks are built on this principle.'),
      S('dims', 'High dimensions', {}, 'One warning about high dimensions. For random points in two dimensions, the nearest neighbour is far closer than the farthest one. In a thousand dimensions the ratio of nearest to farthest distance rises to about point eight nine: almost every point looks equally far away.'),
      S('question', 'Pause and think', { q: 'Two embeddings have cosine similarity 0.95, but one vector is ten times longer. Are they similar in meaning?', a: 'Yes. Cosine similarity ignores length, and their directions almost match. Length often reflects things like word frequency or confidence rather than meaning.' }, 'Another question. Two embeddings have a cosine similarity of point nine five, but one vector is ten times longer than the other. Are they similar in meaning? Yes. Cosine similarity ignores length, and their directions almost match. Length often reflects frequency or confidence rather than meaning.'),
      S('bullets', 'Practical tips', { head: 'Practical tips', items: ['Normalise — divide by the norm before comparing directions', 'Scale features — so no single one dominates distances', 'Prefer cosine — for comparing embeddings', 'Vectorise — never loop over components in Python'] }, 'Some practical tips. Normalise vectors before comparing directions. Scale your features so that no single feature, like income measured in dollars, dominates the distances. Prefer cosine similarity when comparing embeddings. And always use vectorised operations instead of Python loops.'),
      S('table', 'Cheat sheet', { head: 'Vector operations cheat sheet', cols: ['Operation', 'Formula', 'Gives', 'Used for'], widths: [1.1, 1.2, 1, 1.6], rows: [['Addition', 'a + b', 'vector', 'combining signals, residual connections'], ['Scaling', 'c · a', 'vector', 'gradient steps, weighting'], ['Dot product', 'Σ aᵢbᵢ', 'number', 'neurons, attention, logits'], ['Norm', '√(a · a)', 'number', 'length, regularisation'], ['Cosine', 'a·b / (‖a‖‖b‖)', 'number in [−1, 1]', 'semantic similarity']] }, 'Here is a cheat sheet. Addition and scaling give new vectors, used for combining signals and taking gradient steps. The dot product, the norm and cosine similarity each give a single number, and they drive neurons, attention, regularisation and semantic search.'),
      S('bullets', 'Recap', { style: 'recap', items: ['A vector is an ordered list of numbers — an arrow in space', 'Norms measure length; distance is the norm of a difference', 'a · b = Σ aᵢbᵢ = ‖a‖ ‖b‖ cos θ', 'Cosine similarity compares directions only', 'Neurons, attention and search are all dot products'] }, 'To recap. A vector is an ordered list of numbers, an arrow in space. Norms measure length, and distance is the norm of a difference. The dot product equals the lengths times the cosine of the angle. Cosine similarity compares directions, and neurons, attention and search are all built on dot products.')
    ],
    takeaways: ['A vector is an ordered list of numbers; geometrically, an arrow from the origin.', 'Vectors add component-wise and scale by multiplying every component.', 'The L2 norm is √(Σvᵢ²); L1 and L∞ are other useful norms with different unit balls.', 'a · b = Σ aᵢbᵢ = ‖a‖‖b‖ cos θ: positive when aligned, zero when orthogonal, negative when opposed.', 'Cosine similarity divides out the lengths and powers semantic search and RAG.', 'A neuron computes w · x + b; attention scores are dot products of queries and keys.'],
    quiz: [
      { q: 'What is [3, 1] · [1, 2]?', a: ['4', '5', '7', '[3, 2]'], c: 1, why: '3×1 + 1×2 = 5.' },
      { q: 'What is the L2 norm of [3, 4]?', a: ['7', '4', '5', '12'], c: 2, why: '√(9 + 16) = 5.' },
      { q: 'Two non-zero vectors have a dot product of 0. They are…', a: ['Parallel', 'Orthogonal (perpendicular)', 'Identical', 'Opposite'], c: 1, why: 'cos θ = 0 means θ = 90°.' },
      { q: 'Why is cosine similarity popular for comparing embeddings?', a: ['It is the only similarity measure', 'It ignores vector length and compares direction only', 'It is always positive', 'It needs no computation'], c: 1, why: 'Direction carries meaning; length often reflects frequency.' },
      { q: 'Which computation does a single neuron perform before its activation?', a: ['w · x + b', 'x / w', 'max(x)', 'a sort of the inputs'], c: 0, why: 'A weighted sum of inputs plus a bias.' }
    ],
    read: ['vectors-and-vector-spaces', 'norms-inner-products-and-distances', 'why-mathematics-matters-for-ml']
  },
  {
    slug: 'matrices-as-transformations', title: 'Matrices as Transformations', track: 'math', level: 'Beginner', deep: true,
    summary: 'See matrices as machines that transform space: matrix–vector products, composition, determinants, inverses and rank — and why every neural-network layer is a matrix.',
    scenes: [
      S('title', 'Introduction', { title: 'Matrices as Transformations', sub: 'Stretching, rotating and squashing space', track: 'Mathematics for ML' }, 'In this deep dive we look at matrices, not as boring grids of numbers, but as machines that transform space. Once you can see what a matrix does geometrically, neural network layers, embeddings, attention and dimensionality reduction all become far easier to understand.'),
      S('definition', 'What is a matrix?', { term: 'Matrix', def: 'A rectangular grid of numbers with m rows and n columns. It maps n-dimensional vectors to m-dimensional vectors.', eg: 'a dense layer with 784 inputs and 128 outputs is a 128 × 784 matrix' }, 'A matrix is a rectangular grid of numbers with m rows and n columns. Its real job is to map vectors with n numbers to vectors with m numbers. A dense neural network layer that takes seven hundred and eighty four inputs and produces one hundred and twenty eight outputs is a matrix of exactly that shape.'),
      S('equation', 'Matrix times vector', { head: 'Matrix × vector', size: 44, parts: [{ t: '[a b; c d]', c: 'violet', note: 'A 2 × 2 matrix' }, { t: ' · ' }, { t: '[x, y]', c: 'cyan', note: 'The input vector' }, { t: ' = ' }, { t: '[ax + by, cx + dy]', c: 'amber', note: 'Each output = one row · the input: a dot product per row' }], below: 'Row view: each output number is a dot product.   Column view: the output mixes the columns.' }, 'Multiplying a matrix by a vector produces a new vector. Each output number is the dot product of one row with the input. There is a second, even more useful view: the output is a mixture of the matrix columns, weighted by the input numbers.'),
      S('transform', 'Columns are destinations', { m: [[1, 1], [0, 1]], name: 'Shear', v: [1, 2] }, 'Here is the column view in pictures. The first column says where the basis vector i hat lands, and the second says where j hat lands. This shear matrix keeps i hat in place but tips j hat over to one, one, and the whole grid follows along.'),
      S('definition', 'Linearity', { term: 'Linear map', def: 'Grid lines stay straight, parallel and evenly spaced, and the origin stays put. Equivalently: A(u + v) = Au + Av and A(cv) = c·Av.', eg: 'because of linearity, knowing where î and ĵ land tells you where every vector lands' }, 'Matrices perform linear maps. Grid lines stay straight, parallel and evenly spaced, and the origin stays fixed. In algebra, the transform of a sum is the sum of the transforms. That is why knowing where the basis vectors land tells you where every single vector lands.'),
      S('transform', 'Rotation', { m: [[0, -1], [1, 0]], name: 'Rotate 90°' }, 'A rotation is also a matrix. Its columns are zero, one and minus one, zero, which sends i hat straight up and j hat to the left. Every vector turns by ninety degrees. Rotations keep lengths and angles intact, so the yellow square keeps its area.'),
      S('transform', 'Scaling', { m: [[2, 0], [0, 0.5]], name: 'Stretch and squash' }, 'A diagonal matrix stretches or squashes along the axes. This one doubles every x coordinate and halves every y coordinate. Feature scaling in machine learning, where each input column is multiplied by its own factor, is exactly a diagonal matrix like this one.'),
      S('question', 'Pause and think', { q: 'Where does the matrix [[2, 0], [0, 0.5]] send the vector [1, 4]?', a: '[2·1 + 0·4, 0·1 + 0.5·4] = [2, 2]. The x part is doubled and the y part is halved.' }, 'Quick check. Where does the stretch and squash matrix, two, zero, zero, one half, send the vector one, four? Think of it row by row. The answer is two, two: the x component is doubled to two, and the y component is halved to two.'),
      S('transform', 'Reflection', { m: [[-1, 0], [0, 1]], name: 'Mirror (reflect across the y-axis)' }, 'A reflection flips space like a mirror. This matrix sends i hat to minus one, zero and leaves j hat alone, so everything is mirrored across the vertical axis. Lengths are preserved, but left and right are swapped. Keep an eye on the yellow square, because orientation is about to matter.'),
      S('definition', 'Determinant', { term: 'Determinant', def: 'det [[a, b], [c, d]] = ad − bc: the factor by which the matrix scales areas (volumes in 3-D). A negative sign means orientation flips.', eg: 'det = 0 means space is squashed flat — information is lost' }, 'The determinant tells you how much a matrix scales area. For a two by two matrix it is a times d minus b times c. A determinant of three triples every area. A negative determinant flips orientation, like a mirror. And a determinant of zero squashes space flat.'),
      S('question', 'Pause and think', { q: 'What is the determinant of the shear matrix [[1, 1], [0, 1]]? What does that say about areas?', a: 'det = 1·1 − 1·0 = 1. The shear slants the square into a parallelogram, but its area stays exactly the same.' }, 'Pause and think. What is the determinant of the shear matrix we saw earlier, one, one, zero, one? It is one times one minus one times zero, which equals one. The shear slants the square into a parallelogram, but the area stays exactly the same.'),
      S('transform', 'Squashing space', { m: [[1, 2], [0.5, 1]], name: 'Singular matrix' }, 'Here is a matrix with determinant zero: one times one minus two times one half. Both basis vectors land on the same line, so the whole plane collapses onto that line. Different inputs end up at the same output, and there is no way to undo it.'),
      S('definition', 'Inverse', { term: 'Inverse A⁻¹', def: 'The matrix that undoes A: A⁻¹A = I. It exists only when det A ≠ 0.', eg: 'solving Ax = b for x is x = A⁻¹b (in practice, use a solver rather than forming the inverse)' }, 'The inverse of a matrix undoes it, returning every vector to where it started. It exists only when the determinant is not zero, because you cannot unsquash a flattened space. Solving a system of linear equations is the same as applying an inverse, though in practice we use stable solvers.'),
      S('equation', 'Linear regression in matrix form', { head: 'Solving for the best weights', size: 50, parts: [{ t: 'w', c: 'amber', note: 'The best-fitting weights' }, { t: ' = ' }, { t: '(XᵀX)⁻¹', c: 'violet', note: 'Inverse of the (unnormalised) feature covariance' }, { t: 'Xᵀy', c: 'cyan', note: 'How each feature lines up with the target' }], below: 'The normal equations of least squares — pure matrix algebra' }, 'Inverses appear in a classic formula. The least squares weights of linear regression are X transpose X, inverted, times X transpose y. These are called the normal equations. With millions of rows we switch to gradient descent, but for modest data this single matrix formula gives the exact answer.'),
      S('scatter-fit', 'Regression as a projection', {}, 'Geometrically, linear regression projects the vector of targets onto the space spanned by the feature columns. The fitted line is the closest point in that space, and the residuals, the gaps between the points and the line, are perpendicular to it. Matrix algebra and geometry tell the same story.'),
      S('definition', 'Rank', { term: 'Rank', def: 'The number of independent directions a matrix can output — the dimension of its column space.', eg: 'a 1000 × 1000 matrix of rank 8 squeezes everything into an 8-dimensional subspace' }, 'Rank counts how many independent directions a matrix can produce. A full rank two by two matrix covers the whole plane. The singular matrix we just saw has rank one. Low rank matrices are cheap to store, an idea that fine tuning methods like LoRA exploit.'),
      S('lora', 'Low rank in practice', {}, 'LoRA is a beautiful use of rank. Instead of updating a huge weight matrix during fine tuning, it learns the change as the product of two thin matrices of small rank. Far fewer numbers need to be trained and stored, yet the adapted model performs well.'),
      S('matmul', 'Matrix multiplication', {}, 'Multiplying two matrices, A times B, gives a new matrix C. Each entry of C is the dot product of a row of A with a column of B. Watch the cells fill one by one. The inner sizes must match: a two by three matrix times a three by two gives two by two.'),
      S('transform', 'Composition', { m: [[0, -1], [1, 0]], m2: [[1.5, 0], [0, 0.5]], name: 'Rotate, then stretch' }, 'Why multiply matrices at all? Because applying one transformation after another is itself a single matrix: the product. Here we rotate by ninety degrees and then stretch. The combined effect equals the single matrix B times A. Note that order matters: rotate then stretch differs from stretch then rotate.'),
      S('question', 'Pause and think', { q: 'Is matrix multiplication commutative — is AB always equal to BA?', a: 'No. In general AB ≠ BA: rotating then stretching is not the same as stretching then rotating. (And the shapes may not even allow BA.)' }, 'Pause and think. Is matrix multiplication commutative? In other words, is A times B always equal to B times A? The answer is no. Rotating and then stretching gives a different result from stretching and then rotating, and sometimes the shapes do not even allow the reverse product.'),
      S('network', 'Layers are matrices', { layers: [4, 6, 6, 3], mode: 'forward' }, 'Now to neural networks. Each layer of a network takes a vector of activations and multiplies it by a weight matrix, adds a bias vector, and applies an activation function. The arrows between two layers are exactly the entries of one weight matrix.'),
      S('equation', 'A layer in one line', { head: 'A dense layer', size: 58, parts: [{ t: 'h', c: 'amber', note: 'The output activations (a vector)' }, { t: ' = ' }, { t: 'σ', c: 'pink', note: 'A non-linear activation, applied element by element' }, { t: '(' }, { t: 'W', c: 'violet', note: 'Weight matrix: one row per output neuron' }, { t: 'x', c: 'cyan', note: 'The input vector' }, { t: ' + b)', c: 'green', note: 'Bias vector' }], below: 'Without σ, stacked layers would collapse into one matrix' }, 'A whole dense layer fits in one line: h equals sigma of W x plus b. W has one row per output neuron. The activation function sigma is essential. Without it, stacking many layers would just multiply matrices together, collapsing into one single linear layer.'),
      S('question', 'Pause and think', { q: 'Why would a 10-layer network with no activation functions be no more powerful than a single layer?', a: 'Because W₁₀…W₂W₁ is itself one matrix. Composing linear maps gives a linear map, so the whole stack collapses to one layer.' }, 'Here is a deeper question. Why would a ten layer network without any activation functions be no more powerful than a single layer? Because the product of all ten weight matrices is itself just one matrix. Composing linear maps always gives another linear map.'),
      S('stats', 'Parameter counts', { head: 'Parameters in one dense layer = inputs × outputs + biases', items: [['100,480', '784 → 128', 'a small digit-classifier layer'], ['16.8M', '4,096 → 4,096', 'one attention projection in a 7B-parameter LLM'], ['45.1M', '4,096 → 11,008', 'one MLP projection in the same model']] }, 'The size of a weight matrix is the number of inputs times the number of outputs, plus one bias per output. A small digit classifier layer has about one hundred thousand parameters. A single projection inside a seven billion parameter language model has around seventeen to forty five million.'),
      S('definition', 'Batches', { term: 'Batches as matrices', def: 'Stack many input vectors as the rows of a matrix X, and one matrix multiply XWᵀ processes the whole batch at once.', eg: 'a batch of 64 images of 784 pixels is a 64 × 784 matrix' }, 'Matrices also let us process many examples at once. Stack a batch of input vectors as the rows of a matrix, and a single matrix multiplication handles the whole batch. That is why GPUs, which excel at huge matrix products, made deep learning practical.'),
      S('code', 'In code', { head: 'Matrices in NumPy', file: 'layer.py', lines: ['import numpy as np', '', 'A = np.array([[1, 2, 0], [3, 1, 2]])   # 2 x 3', 'B = np.array([[2, 1], [0, 3], [1, 1]])  # 3 x 2', 'print(A @ B)             # [[2 7] [8 8]]', '', 'W = np.random.randn(128, 784) * 0.01   # layer weights', 'X = np.random.rand(64, 784)            # batch of 64 inputs', 'H = np.maximum(0, X @ W.T)             # 64 x 128, ReLU'], hl: [[2, 4], [6, 7], 8], notes: ['Matrix product with @ — the same product we animated', 'A layer’s weight matrix and a batch of inputs', 'One matrix multiply + ReLU processes all 64 examples'] }, 'In code, the at operator multiplies matrices. The two by three matrix times the three by two matrix gives the same answer we animated. Then a layer’s weights and a batch of sixty four inputs are processed with one matrix multiplication followed by a ReLU.'),
      S('table', 'Special matrices', { head: 'Matrices worth recognising', cols: ['Matrix', 'What it does', 'Where it appears'], widths: [1, 1.5, 1.6], rows: [['Identity I', 'leaves every vector unchanged', 'residual connections, initialisation'], ['Diagonal', 'scales each axis separately', 'feature scaling, Σ in SVD'], ['Orthogonal', 'rotates or reflects; keeps lengths', 'PCA bases, stable initialisation'], ['Symmetric', 'A = Aᵀ; real eigenvalues', 'covariance matrices, kernels'], ['Low-rank', 'squeezes into few directions', 'LoRA, compression, recommendations']] }, 'Some matrices are worth recognising on sight. The identity changes nothing. Diagonal matrices scale each axis. Orthogonal matrices rotate without changing lengths. Symmetric matrices, like covariance matrices, have real eigenvalues. And low rank matrices squeeze everything into a few directions.'),
      S('definition', 'Transpose', { term: 'Transpose Aᵀ', def: 'Flip a matrix over its diagonal: rows become columns. (AB)ᵀ = BᵀAᵀ.', eg: 'the gradient of a layer uses Wᵀ to send errors backwards' }, 'The transpose flips a matrix over its diagonal, turning rows into columns. It shows up constantly: a dot product is a transpose times a vector, covariance matrices are X transpose X, and backpropagation sends error signals backwards through a layer using the transposed weight matrix.'),
      S('backprop-graph', 'Matrices in backpropagation', {}, 'During training, gradients flow backwards through the same computational graph. For a matrix layer, the gradient with respect to the input is the transposed weight matrix times the incoming gradient. So the forward pass and the backward pass are both matrix products.'),
      S('attention', 'Attention is a matrix', { mode: 'matrix' }, 'Attention weights themselves form a matrix: one row for each word that is looking, one column for each word it looks at. Multiplying this matrix by the matrix of value vectors mixes information between positions. A transformer layer is essentially a carefully arranged sequence of matrix products.'),
      S('pipeline', 'Transformations everywhere', { head: 'Matrices across AI', steps: ['Embeddings', 'Attention', 'MLP', 'PCA', 'Graphics & vision'], desc: ['An embedding table is a matrix: one row per token.', 'Queries, keys and values come from three projection matrices.', 'Two big matrices with an activation in between.', 'Rotate data onto its directions of greatest variance.', 'Rotations, scalings and projections of images and 3-D points.'] }, 'Matrices appear throughout AI. An embedding table is a matrix with one row per token. Attention creates queries, keys and values with three projection matrices. Transformer MLP blocks are two big matrices. PCA is a rotation, and computer vision is full of geometric transformations.'),
      S('question', 'Pause and think', { q: 'A matrix maps 3-D inputs to 2-D outputs. Can it have an inverse?', a: 'No. It is not square, and it must lose information: a whole line of 3-D inputs lands on each 2-D output. Only square matrices with det ≠ 0 are invertible.' }, 'One more question. A matrix maps three dimensional inputs to two dimensional outputs. Can it have an inverse? No. It is not square, and it necessarily loses information, because many different inputs share each output. Only square matrices with non zero determinant can be inverted.'),
      S('bullets', 'Common pitfalls', { head: 'Common pitfalls', items: ['Shape errors — (m×n)(n×k): inner sizes must match', 'Order — AB ≠ BA in general', 'Element-wise vs matrix product — * is not @ in NumPy', 'Inverting — prefer np.linalg.solve to computing A⁻¹'] }, 'Watch out for common pitfalls. Shape errors are the most frequent bug in deep learning code, so always check inner sizes. Remember that order matters. In NumPy the star operator multiplies element by element, while the at operator is the matrix product. And prefer a solver over computing an inverse.'),
      S('bullets', 'Recap', { style: 'recap', items: ['A matrix is a linear transformation of space', 'Columns show where the basis vectors land', 'det = area scaling; det = 0 → squashed, not invertible', 'Matrix product = composition of transformations', 'Every dense layer computes σ(Wx + b)'] }, 'To recap. A matrix is a linear transformation of space, and its columns show where the basis vectors land. The determinant measures area scaling, and zero means space is squashed and cannot be inverted. Multiplying matrices composes transformations, and every dense layer computes sigma of W x plus b.')
    ],
    takeaways: ['A matrix maps n-dimensional vectors to m-dimensional vectors; its columns are where the basis vectors land.', 'Matrix–vector products are dot products with each row, or mixtures of the columns.', 'The determinant is the area/volume scaling factor; det = 0 means information is lost and no inverse exists.', 'Rank counts independent output directions; low-rank structure powers LoRA and compression.', 'Matrix multiplication composes transformations and is not commutative.', 'A dense layer computes σ(Wx + b); without non-linearities, stacked layers collapse to one matrix.'],
    quiz: [
      { q: 'What is the determinant of [[2, 0], [0, 3]]?', a: ['5', '6', '0', '1'], c: 1, why: '2×3 − 0×0 = 6: areas grow six-fold.' },
      { q: 'A (2×3) matrix times a (3×4) matrix gives…', a: ['a 3×3 matrix', 'a 2×4 matrix', 'an error', 'a 4×2 matrix'], c: 1, why: 'Outer sizes remain: (2×3)(3×4) → 2×4.' },
      { q: 'What does det(A) = 0 tell you?', a: ['A is a rotation', 'A squashes space into fewer dimensions and has no inverse', 'A is the identity', 'A doubles all areas'], c: 1, why: 'Zero area scaling means collapse.' },
      { q: 'Why do neural networks need activation functions between layers?', a: ['To make training slower', 'Without them, stacked linear layers collapse to one linear map', 'To reduce the number of parameters', 'To store the bias'], c: 1, why: 'A product of matrices is still one matrix.' },
      { q: 'In NumPy, what does A @ B compute?', a: ['Element-wise product', 'Matrix product', 'Transpose', 'Determinant'], c: 1, why: '@ is matrix multiplication; * is element-wise.' }
    ],
    read: ['matrices-and-linear-transformations', 'tensors-and-tensor-operations', 'lora-and-parameter-efficient-fine-tuning']
  },
  {
    slug: 'eigenvectors-svd-and-pca', title: 'Eigenvectors, SVD and PCA', track: 'math', level: 'Intermediate', deep: true,
    summary: 'Find the directions a matrix does not turn, break any matrix into rotate–stretch–rotate, and use it to compress data with principal component analysis.',
    scenes: [
      S('title', 'Introduction', { title: 'Eigenvectors, SVD and PCA', sub: 'The hidden axes inside every matrix', track: 'Mathematics for ML' }, 'This deep dive is about the hidden axes inside matrices. Eigenvectors reveal the directions a transformation does not turn. The singular value decomposition breaks any matrix into simple steps. And principal component analysis uses both to compress data. These ideas appear all over machine learning.'),
      S('transform', 'Most vectors turn', { m: [[2, 1], [1, 2]], name: 'A = [[2, 1], [1, 2]]', v: [1, 0] }, 'Watch this matrix transform the plane. Most vectors get knocked off their original line: the orange vector starts pointing right, and ends up pointing up and to the right. But are there special directions that do not turn at all, and only get stretched?'),
      S('eigen', 'Eigenvectors', { m: [[2, 1], [1, 2]] }, 'Yes. These are the eigenvectors. Along the diagonal direction one, one, every vector is simply stretched by three. Along the direction one, minus one, vectors keep their length, a stretch of exactly one. All the other arrows turn. The stretch factors, three and one, are called eigenvalues.'),
      S('equation', 'The eigen equation', { head: 'The eigenvalue equation', size: 64, parts: [{ t: 'A', c: 'violet', note: 'The matrix (the transformation)' }, { t: 'v', c: 'cyan', note: 'An eigenvector: a direction that does not turn' }, { t: ' = ' }, { t: 'λ', c: 'amber', note: 'The eigenvalue: how much v is stretched (or flipped if negative)' }, { t: 'v', c: 'cyan' }], below: 'Applying A to v is the same as just multiplying v by a number' }, 'In symbols, A times v equals lambda times v. Applying the whole matrix to an eigenvector gives the same result as multiplying it by a single number, lambda, the eigenvalue. A negative lambda flips the vector around, and a lambda of zero squashes that direction completely.'),
      S('definition', 'Finding them', { term: 'Characteristic equation', def: 'Eigenvalues solve det(A − λI) = 0. For [[2, 1], [1, 2]]: (2 − λ)² − 1 = 0, so λ = 3 or λ = 1.', eg: 'then solve (A − λI)v = 0 for each λ to get its eigenvector' }, 'How do we find them? Eigenvalues solve the equation determinant of A minus lambda times the identity equals zero. For our matrix that gives two minus lambda, squared, minus one equals zero, so lambda is three or one. Then each eigenvector comes from solving a small linear system.'),
      S('question', 'Pause and think', { q: 'A 2-D rotation by 90° turns every vector. How many real eigenvectors does it have?', a: 'None. Every direction turns, so no real vector satisfies Av = λv. (Its eigenvalues are the complex numbers ±i.)' }, 'Pause and think. A rotation by ninety degrees turns every single vector. How many real eigenvectors can it have? The answer is none. No direction stays on its own line, so there is no real solution. Its eigenvalues turn out to be complex numbers.'),
      S('definition', 'Symmetric matrices', { term: 'Spectral theorem', kicker: 'Why symmetric matrices are special', def: 'A real symmetric matrix always has real eigenvalues and a full set of mutually perpendicular eigenvectors: A = QΛQᵀ.', eg: 'covariance matrices are symmetric, so their eigenvectors form an orthonormal basis' }, 'Symmetric matrices, which equal their own transpose, are especially well behaved. The spectral theorem says they always have real eigenvalues and perpendicular eigenvectors. So they can be written as a rotation, a stretch along the axes, and the rotation back. Covariance matrices are symmetric, which matters for PCA.'),
      S('equation', 'Diagonalisation', { head: 'Diagonalisation', size: 56, parts: [{ t: 'A', c: 'violet', note: 'Any symmetric matrix…' }, { t: ' = ' }, { t: 'Q', c: 'cyan', note: 'columns = eigenvectors (a rotation)' }, { t: 'Λ', c: 'amber', note: 'diagonal matrix of eigenvalues (pure stretching)' }, { t: 'Qᵀ', c: 'cyan', note: 'rotate back' }], below: 'Powers are now easy: Aᵏ = QΛᵏQᵀ' }, 'This is called diagonalisation: A equals Q times lambda times Q transpose. In the eigenvector coordinate system, the matrix is just a stretch along each axis. One bonus is that powers become easy, since applying A ten times just raises each eigenvalue to the tenth power.'),
      S('markov', 'Eigenvectors in the wild', {}, 'Eigenvectors appear in surprising places. This weather Markov chain settles into a long run distribution of about forty six percent sunny, twenty eight percent cloudy and twenty six percent rainy. That stationary distribution is an eigenvector of the transition matrix, with eigenvalue one. Google’s original PageRank used the same idea.'),
      S('question', 'Pause and think', { q: 'A direction has eigenvalue 0.5. What happens to that component after applying the matrix 10 times?', a: 'It is multiplied by 0.5¹⁰ ≈ 0.001 — it almost vanishes. Components with |λ| > 1 grow; those with |λ| < 1 shrink away.' }, 'Pause and think. Some direction has eigenvalue one half. What happens to that component if we apply the matrix ten times? It gets multiplied by one half to the power ten, about one thousandth, so it almost vanishes. Eigenvalues above one make components grow, and those below one make them shrink.'),
      S('definition', 'Power iteration', { term: 'Power iteration', def: 'Multiply a random vector by A again and again, normalising each time. It turns towards the eigenvector with the largest |λ|.', eg: 'PageRank computed the importance of billions of web pages this way' }, 'That observation gives a simple algorithm called power iteration. Start with any vector, multiply by the matrix again and again, and rescale each time. The component with the largest eigenvalue grows fastest and soon dominates. PageRank used this idea to rank billions of web pages.'),
      S('gradient-field', 'Eigenvalues as curvature', { a: 0.25, b: 2, lr: 0.4 }, 'Eigenvalues also describe the shape of a loss surface. Near a minimum, the loss is approximately a bowl whose curvature along each direction is an eigenvalue of the Hessian matrix. Here one direction is eight times steeper than the other, which is exactly why gradient descent zig zags.'),
      S('definition', 'Condition number', { term: 'Condition number κ', def: 'κ = λ_max / λ_min: the ratio of the steepest to the flattest curvature. A large κ means an ill-conditioned, slow-to-optimise problem.', eg: 'feature scaling and normalisation layers reduce κ and speed up training' }, 'The ratio of the largest to the smallest eigenvalue is the condition number. A large condition number means a long, narrow valley, where one learning rate is too big for one direction and too small for another. Feature scaling, batch normalisation and adaptive optimisers all help by taming it.'),
      S('definition', 'Beyond square matrices', { term: 'Singular value decomposition', kicker: 'Works for every matrix', def: 'Any m × n matrix can be written A = UΣVᵀ: a rotation, a stretch along the axes, and another rotation.', eg: 'σ₁ ≥ σ₂ ≥ … ≥ 0 are the singular values' }, 'Eigenvectors only work for square matrices, and not even all of those. The singular value decomposition works for every matrix of any shape. It says any matrix can be written as a rotation, then a stretch along the axes, then another rotation. The stretch factors are called singular values.'),
      S('svd', 'Rotate, stretch, rotate', {}, 'Watch the unit circle. First V transpose rotates it, lining up two special input directions with the axes. Then sigma stretches along the axes, by about two point three eight and one point two six. Finally U rotates the result. The circle becomes an ellipse, exactly as the original matrix would do.'),
      S('equation', 'Rank-one pieces', { head: 'SVD as a sum of simple pieces', size: 48, parts: [{ t: 'A', c: 'violet', note: 'Any matrix…' }, { t: ' = ' }, { t: 'σ₁u₁v₁ᵀ', c: 'amber', note: 'The most important rank-one piece' }, { t: ' + ' }, { t: 'σ₂u₂v₂ᵀ', c: 'pink', note: 'The next most important piece' }, { t: ' + …', c: 'muted' }], below: 'Keep the top k pieces → the best rank-k approximation (Eckart–Young theorem)' }, 'Another way to read the SVD: any matrix is a sum of simple rank one pieces, each weighted by a singular value, sorted from most to least important. Keeping only the top k pieces gives the best possible rank k approximation. This is the mathematical heart of compression.'),
      S('bars', 'Singular values decay', { head: 'Singular values of a typical image (illustrative)', labels: ['σ₁', 'σ₂', 'σ₃', 'σ₄', 'σ₅', 'σ₆', 'σ₇', 'σ₈'], values: [100, 42, 21, 12, 7, 4, 2.5, 1.5], unit: 'size', dec: 1 }, 'In real data, singular values usually fall off quickly. For a typical photograph, the first few carry most of the structure and the rest describe fine detail and noise. That is why keeping a small number of components can reproduce an image, or a dataset, surprisingly well.'),
      S('question', 'Pause and think', { q: 'An image matrix is 1000 × 1000. Storing its rank-20 approximation needs how many numbers, roughly?', a: 'About 20 × (1000 + 1000 + 1) ≈ 40,000 — versus 1,000,000 for the full image: a 25× saving.' }, 'Pause and think. A grayscale image is a thousand by a thousand matrix. Roughly how many numbers are needed to store its rank twenty approximation? Each piece needs a column of a thousand, a row of a thousand and one singular value, so about forty thousand numbers, instead of one million.'),
      S('definition', 'PCA', { term: 'Principal Component Analysis', def: 'Find the orthogonal directions of greatest variance in the data (the principal components) and project onto the top few.', eg: 'from 100 correlated features to 10 components that keep 95% of the variance' }, 'Now to principal component analysis. PCA finds the perpendicular directions along which the data varies the most, called principal components, and projects the data onto the top few. You might compress a hundred correlated features into ten components while keeping most of the variance.'),
      S('pca', 'PCA in action', {}, 'Here PCA searches for the direction of maximum spread. The first principal component points along the long axis of the cloud. Projecting onto it keeps most of the information in one number per point. The second component, perpendicular to the first, captures what remains.'),
      S('pipeline', 'The PCA recipe', { head: 'PCA step by step', steps: ['Centre', 'Covariance', 'Eigen / SVD', 'Sort', 'Project'], desc: ['Subtract the mean of each feature.', 'Compute the covariance matrix C = XᵀX / (n − 1).', 'Eigenvectors of C (or the SVD of X) give the directions.', 'Order them by eigenvalue: the variance each one explains.', 'Multiply the data by the top-k directions.'] }, 'Here is the PCA recipe. Centre the data by subtracting each feature’s mean. Compute the covariance matrix. Find its eigenvectors, or equivalently take the SVD of the data. Sort the directions by eigenvalue, which is the variance they explain, and project onto the top ones.'),
      S('equation', 'Why eigenvectors?', { head: 'The link between PCA and eigenvectors', size: 44, parts: [{ t: 'maximise', c: 'muted' }, { t: ' wᵀCw', c: 'amber', note: 'The variance of the data projected onto direction w' }, { t: ' subject to ' }, { t: '‖w‖ = 1', c: 'cyan', note: 'Only the direction matters' }], below: 'The answer is the eigenvector of C with the largest eigenvalue — and that eigenvalue is the variance captured' }, 'Why do eigenvectors appear? The variance of the data projected onto a unit direction w is w transpose C w. Maximising that is exactly solved by the top eigenvector of the covariance matrix, and its eigenvalue is the variance it captures. PCA is an eigenvalue problem.'),
      S('bars', 'Explained variance', { head: 'Explained variance by component (example)', labels: ['PC1', 'PC2', 'PC3', 'PC4', 'PC5', 'PC6'], values: [62, 21, 9, 4, 3, 1], unit: '% of variance', suffix: '%' }, 'A scree plot shows how much variance each component explains. In this example the first component explains sixty two percent, the second twenty one, and the third nine. The first three together keep ninety two percent of the variance, so three numbers per example might be enough.'),
      S('code', 'In code', { head: 'PCA with scikit-learn and NumPy', file: 'pca.py', lines: ['import numpy as np', 'from sklearn.decomposition import PCA', '', 'X = np.loadtxt("features.csv", delimiter=",")', 'pca = PCA(n_components=0.95)       # keep 95% variance', 'Z = pca.fit_transform(X)', 'print(X.shape, "->", Z.shape)', 'print(pca.explained_variance_ratio_)', '', 'U, S, Vt = np.linalg.svd(X - X.mean(0), full_matrices=False)'], hl: [[4, 5], [6, 7], 9], notes: ['Ask for enough components to keep 95% of the variance', 'Inspect the new shape and the variance each component explains', 'The same directions straight from the SVD: rows of Vt'] }, 'In code, scikit learn makes PCA a two liner. Ask for enough components to keep ninety five percent of the variance, fit, and transform. You can inspect how much variance each component explains. Under the hood it is an SVD of the centred data, which you can call directly with NumPy.'),
      S('code', 'Eigenvectors in NumPy', { head: 'Eigenvalues and eigenvectors in NumPy', file: 'eigen.py', lines: ['import numpy as np', '', 'A = np.array([[2.0, 1.0], [1.0, 2.0]])', 'vals, vecs = np.linalg.eigh(A)      # for symmetric matrices', 'print(vals)                          # [1. 3.]', 'print(vecs)                          # columns = unit eigenvectors', '', 'v = vecs[:, 1]', 'print(A @ v, 3 * v)                  # identical: Av = 3v'], hl: [[2, 3], [4, 5], [7, 8]], notes: ['eigh is the fast, stable routine for symmetric matrices', 'Eigenvalues 1 and 3, with their unit eigenvectors as columns', 'Check the definition: A times v equals 3 times v'] }, 'In NumPy, the eigh function handles symmetric matrices quickly and stably. For our matrix it returns eigenvalues one and three, with the unit eigenvectors as the columns of a matrix. Multiplying A by the second eigenvector gives exactly three times that vector, confirming the definition.'),
      S('compare', 'PCA: strengths and limits', { head: 'When to use PCA', left: { title: 'Great for', items: ['Compressing correlated features', 'Visualising data in 2-D or 3-D', 'Removing noise before modelling'], color: 'green' }, right: { title: 'Watch out', items: ['Only finds linear structure', 'Sensitive to feature scaling — standardise first', 'Components can be hard to interpret'], color: 'amber' } }, 'PCA is great for compressing correlated features, visualising high dimensional data and removing noise. But it only finds linear structure, it is sensitive to feature scale, so standardise first, and components can be hard to interpret. For curved structure, methods like t SNE or UMAP help with visualisation.'),
      S('question', 'Pause and think', { q: 'You forget to standardise, and one feature is income in dollars (variance ≈ 10⁸) while others are ratios near 1. What will PC1 be?', a: 'Almost exactly the income axis. PCA chases variance, and income’s huge scale dominates — so standardise features before PCA.' }, 'Pause and think. You forget to standardise, and one feature is income in dollars, with enormous variance, while the others are small ratios. What will the first principal component be? Almost exactly the income axis. PCA chases raw variance, so the biggest scale wins. Always standardise first.'),
      S('pipeline', 'Beyond PCA', { head: 'The same maths, many applications', steps: ['Recommenders', 'LoRA', 'Latent semantics', 'Spectral clustering', 'Stability'], desc: ['Matrix factorisation: users × items ≈ low-rank product.', 'Fine-tuning updates as a low-rank product BA.', 'SVD of a term–document matrix finds topics (LSA).', 'Eigenvectors of a graph Laplacian reveal clusters.', 'Largest eigenvalues of weight matrices govern exploding signals.'] }, 'The same mathematics powers many applications. Recommender systems factor a user by item matrix into a low rank product. LoRA learns low rank updates. Latent semantic analysis takes the SVD of a term document matrix. Spectral clustering uses eigenvectors of a graph, and eigenvalues explain exploding signals in deep networks.'),
      S('lora', 'Low rank in fine-tuning', { r: 8 }, 'Low rank structure also explains why parameter efficient fine tuning works. The LoRA authors found that the change a large pre-trained model needs to adapt to a new task has a low intrinsic rank. So instead of a full update, they learn two thin matrices, and very small ranks, such as four or eight, often work well.'),
      S('table', 'Summary table', { head: 'Eigen-decomposition vs SVD', cols: ['', 'Eigen-decomposition', 'SVD'], rows: [['Works for', 'square (diagonalisable) matrices', 'any m × n matrix'], ['Form', 'A = QΛQ⁻¹ (QΛQᵀ if symmetric)', 'A = UΣVᵀ'], ['Values', 'eigenvalues λ (can be negative or complex)', 'singular values σ ≥ 0'], ['ML uses', 'PCA on covariance, Markov chains, graphs', 'PCA on data, compression, LoRA, recommenders']] }, 'To compare the two. Eigen decomposition works for square, diagonalisable matrices, and its eigenvalues can be negative or even complex. The SVD works for any matrix, and its singular values are never negative. For symmetric positive matrices like covariance matrices, the two coincide.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Eigenvectors keep their direction: Av = λv', 'Symmetric matrices have perpendicular eigenvectors', 'SVD: every matrix = rotate · stretch · rotate', 'Top singular pieces give the best low-rank approximation', 'PCA = eigenvectors of the covariance matrix'] }, 'To recap. Eigenvectors are directions a matrix only stretches, and eigenvalues are the stretch factors. Symmetric matrices have perpendicular eigenvectors. The SVD writes every matrix as rotate, stretch, rotate, and its top pieces give the best low rank approximation. PCA is simply eigenvectors of the covariance matrix.')
    ],
    takeaways: ['An eigenvector satisfies Av = λv: the matrix only stretches it by λ.', 'Eigenvalues solve det(A − λI) = 0; rotations have no real eigenvectors.', 'Symmetric matrices (like covariance) have real eigenvalues and orthogonal eigenvectors.', 'SVD writes any matrix as UΣVᵀ; truncating it gives the best low-rank approximation.', 'PCA projects centred data onto the top eigenvectors of its covariance matrix.', 'Standardise features before PCA; it only captures linear structure.'],
    quiz: [
      { q: 'What are the eigenvalues of [[2, 1], [1, 2]]?', a: ['2 and 2', '3 and 1', '1 and −1', '4 and 0'], c: 1, why: '(2 − λ)² − 1 = 0 gives λ = 3 or 1.' },
      { q: 'Which decomposition works for ANY rectangular matrix?', a: ['Eigen-decomposition', 'Singular value decomposition', 'Cholesky decomposition', 'None'], c: 1, why: 'SVD exists for every m × n matrix.' },
      { q: 'In PCA, what does the eigenvalue of a component tell you?', a: ['Its colour', 'How much variance that direction captures', 'The number of samples', 'The learning rate'], c: 1, why: 'λ = variance of data projected on that eigenvector.' },
      { q: 'Why should you standardise features before PCA?', a: ['PCA needs integers', 'Features with large scales would dominate the components', 'It makes PCA non-linear', 'It removes outliers'], c: 1, why: 'PCA maximises raw variance.' },
      { q: 'Keeping the top k singular values gives…', a: ['A random matrix', 'The best rank-k approximation of the matrix', 'The inverse matrix', 'The transpose'], c: 1, why: 'Eckart–Young theorem.' }
    ],
    read: ['eigenvalues-and-eigenvectors', 'singular-value-decomposition', 'principal-component-analysis']
  },
  {
    slug: 'calculus-for-machine-learning', title: 'Calculus for Machine Learning: Derivatives, Gradients and the Chain Rule', track: 'math', level: 'Intermediate', deep: true,
    summary: 'How models learn by following slopes: derivatives, partial derivatives, gradients, gradient descent, saddle points and the chain rule that makes backpropagation possible.',
    scenes: [
      S('title', 'Introduction', { title: 'Calculus for Machine Learning', sub: 'Derivatives, gradients and the chain rule', track: 'Mathematics for ML' }, 'Training a neural network means adjusting millions of numbers so that a loss gets smaller. The only reason this is possible is calculus. In this deep dive we build up derivatives, gradients and the chain rule, and see exactly how they turn into learning.'),
      S('loss-curve', 'Why slopes matter', { lr: 0.1, steps: 20 }, 'Imagine standing on a hilly loss curve in the fog. You cannot see the lowest point, but you can feel which way the ground slopes under your feet. Take a small step downhill, feel again, and repeat. That is gradient descent, and the slope you feel is the derivative.'),
      S('definition', 'The derivative', { term: 'Derivative', def: 'f′(x) = lim (h → 0) [f(x + h) − f(x)] / h — the instantaneous rate of change: the slope of the curve at x.', eg: 'if f′(x) = 4, nudging x by 0.01 changes f by about 0.04' }, 'The derivative measures the instantaneous rate of change: how much the output changes for a tiny nudge of the input. Formally, it is the limit of rise over run as the run shrinks to zero. If the derivative is four, a tiny step of point zero one changes the output by about point zero four.'),
      S('derivative', 'Secant to tangent', { f: 'x*x', fl: 'x²', x0: 1 }, 'Let us watch the limit happen for f of x equals x squared at x equals one. With a step of two, the secant slope is four. As the step shrinks to one, a half, a tenth and a hundredth, the slope gets closer and closer to two. In the limit we get the tangent line, with slope exactly two.'),
      S('table', 'Derivative rules', { head: 'Derivatives you will meet constantly', cols: ['Function', 'Derivative', 'Where in ML'], widths: [1, 1, 1.6], rows: [['xⁿ', 'n·xⁿ⁻¹', 'squared error, polynomial features'], ['eˣ', 'eˣ', 'softmax, sigmoid'], ['ln x', '1/x', 'log-likelihood, cross-entropy'], ['σ(x) = 1/(1+e⁻ˣ)', 'σ(x)(1 − σ(x))', 'logistic regression, gates'], ['max(0, x)', '0 if x < 0, 1 if x > 0', 'ReLU activations']] }, 'You do not need to derive everything from limits. A handful of rules cover most of machine learning. Powers bring the exponent down. The exponential is its own derivative. The logarithm gives one over x. The sigmoid’s derivative is sigma times one minus sigma, and ReLU’s derivative is zero or one.'),
      S('plot', 'The sigmoid and its slope', { head: 'Sigmoid and its derivative', x: [-6, 6], y: [-0.05, 1.05], fns: [{ f: '1/(1+exp(-x))', label: 'σ(x)', lx: 4.5, dy: -24 }, { f: '(1/(1+exp(-x)))*(1-1/(1+exp(-x)))', c: 'pink', label: 'σ′(x) — max 0.25', lx: 1.2, dy: -30, align: 'left' }], tangent: { i: 0, from: -4, to: 3 }, note: 'The slope is largest (0.25) at 0 and almost zero in the flat tails — a cause of vanishing gradients.' }, 'Here is the sigmoid with its derivative in pink. The amber tangent line slides along the curve. The slope is largest at zero, where it equals one quarter, and almost vanishes in the flat tails. This tiny maximum slope is one reason deep networks of sigmoids suffer from vanishing gradients.'),
      S('question', 'Pause and think', { q: 'f(x) = x² has derivative 2x. At x = 3, which way should gradient descent move x, and why?', a: 'Left (decrease x). The slope 2·3 = 6 is positive, so f increases to the right; stepping against the slope lowers f.' }, 'Pause and think. The function x squared has derivative two x. At x equals three, which way should gradient descent move? The slope is six, which is positive, meaning the function rises to the right. So we move left, against the slope, to go downhill.'),
      S('question', 'Pause and think', { q: 'What is the derivative of sin(x²)?', hint: 'Outer function, then inner function.', a: 'cos(x²) · 2x — the derivative of the outer function (evaluated at x²) times the derivative of the inner function.' }, 'A quick warm up. What is the derivative of the sine of x squared? We will meet the rule formally soon, but have a try. The answer is the cosine of x squared, times two x: the derivative of the outer function, times the derivative of the inner one.'),
      S('definition', 'Partial derivatives', { term: 'Partial derivative ∂f/∂xᵢ', def: 'With many inputs, change one at a time and hold the others fixed. Each partial derivative is the slope along one axis.', eg: 'f(x, y) = x²y → ∂f/∂x = 2xy and ∂f/∂y = x²' }, 'Models have many parameters, not one. A partial derivative measures the slope along one input while all the others are frozen. For x squared times y, the partial derivative with respect to x is two x y, and with respect to y it is x squared.'),
      S('definition', 'The gradient', { term: 'Gradient ∇f', def: 'The vector of all partial derivatives: ∇f = [∂f/∂x₁, …, ∂f/∂xₙ]. It points in the direction of steepest increase.', eg: 'its length is how steep that increase is; −∇f points steepest downhill' }, 'Collect all the partial derivatives into one vector and you have the gradient. The gradient points in the direction of steepest ascent, and its length tells you how steep the climb is. So minus the gradient points straight downhill. For a network, this vector has one entry per parameter.'),
      S('gradient-field', 'The gradient field', { a: 0.25, b: 2, lr: 0.4 }, 'Here is a bowl shaped loss surface drawn as contour lines, with arrows showing minus the gradient at many points. The ball follows the arrows downhill. Notice how it zig zags across the steep direction while crawling along the gentle one. That shape comes from very different curvatures along the two axes.'),
      S('equation', 'The update rule', { head: 'Gradient descent', size: 58, parts: [{ t: 'θ', c: 'cyan', note: 'All the model’s parameters' }, { t: ' ← ' }, { t: 'θ', c: 'cyan' }, { t: ' − ' }, { t: 'η', c: 'amber', note: 'The learning rate: how big a step to take' }, { t: '∇L(θ)', c: 'pink', note: 'The gradient of the loss: which way is uphill' }], below: 'Repeat thousands or millions of times' }, 'The update rule is simple. Every parameter moves a small step against the gradient of the loss, scaled by the learning rate, eta. Repeat thousands or millions of times. Every modern optimiser, including momentum and Adam, is a refinement of this one line.'),
      S('loss-curve', 'Learning rate too small', { lr: 0.02, steps: 20, verdict: 'Too small: painfully slow' }, 'The learning rate matters enormously. With a tiny learning rate, each step is safe but minuscule. After twenty steps we have barely moved, and training would take forever. Models trained this way waste time and compute.'),
      S('loss-curve', 'Learning rate too large', { lr: 2.6, steps: 20, verdict: 'Too large: overshoots and bounces' }, 'With a learning rate that is too large, each step overshoots the minimum and lands on the other side of the valley. The point bounces back and forth, and if the rate is larger still, the loss can explode entirely. Finding a good learning rate is one of the first jobs when training a model.'),
      S('definition', 'Curvature', { term: 'Second derivative & Hessian', def: 'f″(x) measures how the slope itself changes — the curvature. With many inputs, the matrix of second partial derivatives is the Hessian H.', eg: 'positive curvature = a valley floor · negative = a hilltop · H’s eigenvalues give the curvature in each direction' }, 'The second derivative measures how the slope itself changes: the curvature. Positive curvature means a valley, and negative curvature means a hilltop. With many parameters, the second derivatives form the Hessian matrix, and its eigenvalues describe the curvature along each direction of the loss surface.'),
      S('definition', 'Convexity', { term: 'Convex function', def: 'A bowl shape: any chord between two points lies above the curve. Every local minimum is the global minimum.', eg: 'linear and logistic regression losses are convex; neural network losses are not' }, 'Some functions are convex, shaped like a bowl, so that any line segment between two points on the curve lies above it. For convex functions, every local minimum is the global minimum, and gradient descent is guaranteed to find it. Linear and logistic regression have convex losses.'),
      S('landscape', 'Non-convex landscapes', { mode: 'hill' }, 'Neural network losses are not convex. Their landscapes have many valleys, ridges and plateaus. Here a simple hill climber gets stuck on a local peak. Surprisingly, in very high dimensions, true bad local minima are rarer than people once feared, and the bigger obstacles are flat regions and saddle points.'),
      S('gradient-field', 'Saddle points', { mode: 'saddle' }, 'This is a saddle point: the surface curves up in one direction and down in another, like a horse’s saddle. The gradient is exactly zero at the centre, yet it is not a minimum. The ball starting almost on the ridge eventually slides away. In high dimensions, most critical points are saddles.'),
      S('question', 'Pause and think', { q: 'At a point the gradient is exactly zero. Is it guaranteed to be a minimum?', a: 'No. It could be a minimum, a maximum or a saddle point. You need curvature (second derivatives, the Hessian) to tell them apart.' }, 'Pause and think. At some point the gradient is exactly zero. Are you guaranteed to be at a minimum? No. A zero gradient could mean a minimum, a maximum or a saddle point. To tell them apart you need the curvature, which is measured by second derivatives, collected in the Hessian matrix.'),
      S('contour', 'Better optimisers', { opts: ['sgd', 'momentum', 'adam'] }, 'Better optimisers use extra tricks. Momentum accumulates a running average of past gradients, so it keeps moving through flat regions and damps the zig zag. Adam also adapts the step size for each parameter separately. On this surface you can see them take very different paths.'),
      S('definition', 'The chain rule', { term: 'Chain rule', def: 'For a composition y = f(g(x)): dy/dx = f′(g(x)) · g′(x). Multiply the local derivatives along the chain.', eg: 'y = (3x + 1)² → dy/dx = 2(3x + 1) · 3' }, 'Now the most important rule for deep learning: the chain rule. When functions are nested, one inside another, the derivative of the whole is the product of the local derivatives along the chain. For three x plus one, squared, the derivative is two times three x plus one, times three.'),
      S('chain-rule', 'Forward and backward', { nodes: [{ l: 'x', v: '2' }, { l: 'u = x²', v: '4', d: 'du/dx = 2x = 4' }, { l: 'y = 3u + 1', v: '13', d: 'dy/du = 3' }], result: 'dy/dx = dy/du · du/dx = 3 × 4 = 12' }, 'Here is the chain rule as a pipeline. The forward pass computes values: x is two, u is four, and y is thirteen. The backward pass multiplies local derivatives from right to left: three times four gives twelve. Change x by a tiny amount, and y changes twelve times as much.'),
      S('definition', 'Jacobians', { term: 'Jacobian matrix', def: 'For a function from n inputs to m outputs, the m × n matrix of all partial derivatives ∂yᵢ/∂xⱼ. The chain rule for vector functions multiplies Jacobians.', eg: 'the Jacobian of a linear layer y = Wx is simply W' }, 'When a function maps many inputs to many outputs, its derivatives form a matrix called the Jacobian. The chain rule for vector functions multiplies Jacobians together. For a linear layer the Jacobian is just the weight matrix, which is why backpropagation is full of transposed weight matrices.'),
      S('backprop-graph', 'Backpropagation', {}, 'Backpropagation is simply the chain rule applied systematically to a computational graph. The forward pass stores every intermediate value. The backward pass starts from the loss and multiplies local derivatives node by node, delivering the gradient for every parameter in one sweep.'),
      S('stats', 'Why backprop wins', { head: 'Why backpropagation is so efficient', items: [['1', 'backward pass', 'gives ALL gradients'], ['≈ 2–3×', 'cost of a forward pass', 'for the backward pass'], ['1,000,000,000+', 'parameters', 'handled the same way']], note: 'Numerical differentiation would need one extra forward pass per parameter.' }, 'Backpropagation is remarkably efficient. A single backward pass, costing roughly two to three forward passes, delivers the gradient for every parameter at once, whether there are a thousand or a billion. Estimating gradients by nudging each parameter separately would need one extra pass per parameter.'),
      S('gradient-flow', 'Vanishing gradients', { both: true }, 'The chain rule also explains a classic problem. In a deep network the gradient is a long product of local derivatives. If those are mostly below one, as with sigmoids, the product shrinks towards zero and early layers stop learning. Skip connections, as in ResNet, give the gradient a shortcut.'),
      S('activation', 'Activations and their slopes', {}, 'The choice of activation function matters because of these slopes. Sigmoid and tanh flatten out for large inputs, so their derivatives vanish there. ReLU has a slope of exactly one for positive inputs, which lets gradients pass through many layers, one reason it made very deep networks trainable.'),
      S('code', 'Autodiff in PyTorch', { head: 'Automatic differentiation in PyTorch', file: 'autodiff.py', lines: ['import torch', '', 'x = torch.tensor(2.0, requires_grad=True)', 'u = x ** 2', 'y = 3 * u + 1', 'y.backward()                 # chain rule, automatically', 'print(y.item(), x.grad)      # 13.0 tensor(12.)', '', 'w = torch.randn(3, requires_grad=True)', 'loss = ((w * torch.tensor([1., 2., 3.])).sum() - 1) ** 2', 'loss.backward(); print(w.grad)   # one partial per weight'], hl: [[2, 4], [5, 6], [8, 10]], notes: ['Build the same chain as before: x → u → y', 'backward() applies the chain rule: dy/dx = 12', 'For many parameters, .grad holds the whole gradient vector'] }, 'In practice nobody differentiates by hand. Frameworks like PyTorch record the forward computation and apply the chain rule automatically. Here the same chain gives y equals thirteen and a gradient of twelve. With a vector of weights, the grad attribute holds one partial derivative per weight.'),
      S('train-loop', 'The training loop', {}, 'Put it all together and you have the training loop. Take a batch of data, run the forward pass, compute the loss, run backpropagation to get the gradient, and let the optimiser take a step. Repeat. Every model you have heard of, from spam filters to GPT, is trained this way.'),
      S('question', 'Pause and think', { q: 'Your loss suddenly becomes NaN after a few hundred steps. Which calculus-related causes should you check first?', a: 'Exploding gradients (try gradient clipping or a lower learning rate) and numerically unstable operations such as log(0) or exp of huge numbers.' }, 'A practical question. Your training loss suddenly becomes not a number after a few hundred steps. What should you check? Most often it is exploding gradients, so lower the learning rate or clip gradients, or a numerically unstable operation such as the log of zero or the exponential of a huge number.'),
      S('bullets', 'Practical tips', { head: 'Practical tips', items: ['Tune the learning rate first — it matters most', 'Watch the loss curve — noisy but trending down is healthy', 'Clip gradients — when training large or recurrent models', 'Check gradients — compare autodiff with finite differences when writing custom layers'] }, 'Some practical tips. Tune the learning rate first, because it matters more than almost anything else. Watch the loss curve. Clip gradients for large or recurrent models. And when you write a custom layer, check its gradients against small finite differences.'),
      S('bullets', 'Recap', { style: 'recap', items: ['The derivative is the slope: the limit of rise over run', 'The gradient collects partial derivatives; −∇L points downhill', 'Gradient descent: θ ← θ − η∇L; the learning rate is crucial', 'Zero gradient can be a minimum, maximum or saddle', 'Chain rule + computational graph = backpropagation'] }, 'To recap. The derivative is the slope, a limit of rise over run. The gradient collects all the partial derivatives, and minus the gradient points downhill. Gradient descent steps against it, with the learning rate setting the size. A zero gradient may be a saddle, and the chain rule applied to a graph is backpropagation.')
    ],
    takeaways: ['A derivative is the limit of rise over run: the slope at a point.', 'The gradient ∇f is the vector of partial derivatives and points in the direction of steepest increase.', 'Gradient descent updates θ ← θ − η∇L; too small a learning rate is slow, too large diverges.', 'Convex losses have a single global minimum; neural-network losses are non-convex with many saddle points.', 'The chain rule multiplies local derivatives; backpropagation applies it to a whole computational graph.', 'Frameworks such as PyTorch compute gradients automatically (autodiff).'],
    quiz: [
      { q: 'What is the derivative of x² at x = 1?', a: ['1', '2', '4', '0.5'], c: 1, why: 'd/dx x² = 2x = 2.' },
      { q: 'Which direction does −∇L point?', a: ['Steepest increase', 'Steepest decrease of the loss', 'Along a contour line', 'Towards the origin'], c: 1, why: 'The gradient points uphill; its negative points downhill.' },
      { q: 'What is the largest value of the sigmoid’s derivative?', a: ['1', '0.5', '0.25', '0'], c: 2, why: 'σ′(0) = 0.5 × 0.5 = 0.25.' },
      { q: 'If y = 3u + 1 and u = x², what is dy/dx at x = 2?', a: ['3', '4', '12', '13'], c: 2, why: 'dy/du · du/dx = 3 × 2x = 3 × 4 = 12.' },
      { q: 'A point with zero gradient that curves up one way and down another is a…', a: ['Global minimum', 'Saddle point', 'Local maximum', 'Learning rate'], c: 1, why: 'Mixed curvature defines a saddle.' }
    ],
    read: ['derivatives-gradients-chain-rule', 'gradient-descent-theory', 'backpropagation-derived']
  },
  {
    slug: 'probability-and-distributions', title: 'Probability and Distributions for ML', track: 'math', level: 'Intermediate', deep: true,
    summary: 'Random variables, expectation and variance, the Bernoulli, binomial and normal distributions, the central limit theorem, Monte Carlo methods and Markov chains — with live simulations.',
    scenes: [
      S('title', 'Introduction', { title: 'Probability and Distributions', sub: 'The mathematics of uncertainty', track: 'Mathematics for ML' }, 'Machine learning is about making good decisions under uncertainty. Data is noisy, labels are imperfect, and predictions are never certain. Probability is the language for all of this. In this deep dive we build the core ideas and watch them come alive in simulations.'),
      S('definition', 'Probability', { term: 'Probability', def: 'A number between 0 and 1 measuring how likely an event is. All outcomes together sum to 1.', eg: 'P(heads) = 0.5 · P(rain tomorrow) = 0.3 · P(this email is spam) = 0.97' }, 'A probability is a number between zero and one measuring how likely something is. Zero means impossible and one means certain, and the probabilities of all possible outcomes add up to one. A spam filter that outputs point nine seven is saying: I am very confident this email is spam.'),
      S('definition', 'Random variables', { term: 'Random variable', def: 'A quantity whose value depends on chance, described by a distribution: which values it can take and how likely each one is.', eg: 'discrete: a die roll (1 … 6) · continuous: tomorrow’s temperature' }, 'A random variable is a quantity whose value depends on chance, like the result of a die roll or tomorrow’s temperature. Its distribution tells us which values are possible and how likely each one is. Discrete variables take separate values; continuous ones take any value in a range.'),
      S('equation', 'Conditional probability', { head: 'Conditional probability', size: 50, parts: [{ t: 'P(A | B)', c: 'cyan', note: 'The probability of A, given that we know B happened' }, { t: ' = ' }, { t: 'P(A and B)', c: 'pink', note: 'How often both happen…' }, { t: ' / ' }, { t: 'P(B)', c: 'amber', note: '…as a fraction of the times B happens' }], below: 'Classifiers output conditional probabilities: P(label | input)' }, 'Conditional probability is the probability of A once we know B has happened. It equals the probability of both, divided by the probability of B. Almost every classifier outputs a conditional probability: the probability of a label, given the input.'),
      S('bayes', 'Bayes’ theorem', {}, 'Bayes’ theorem lets us flip a conditional probability around. Here a disease affects one percent of people, and a test is quite accurate. Yet among everyone who tests positive, most are actually healthy, because healthy people vastly outnumber sick ones. The prior matters enormously.'),
      S('question', 'Pause and think', { q: 'A test is 99% accurate, but the condition affects only 1 in 10,000 people. You test positive. Is it likely you have it?', a: 'Probably not. Among 10,000 people, about 1 true positive but about 100 false positives: roughly a 1% chance. Rare conditions need very specific tests.' }, 'Pause and think. A test is ninety nine percent accurate, but the condition affects only one person in ten thousand. You test positive. Is it likely you have it? Probably not. In ten thousand people there is about one true positive but around a hundred false positives, so the chance is about one percent.'),
      S('confusion', 'Bayes in evaluation', {}, 'Conditional probability is built into how we evaluate classifiers. Precision is the probability that an example really is positive, given that the model predicted positive. Recall is the probability of a positive prediction, given that the example really is positive. Mixing them up is the same mistake as mixing up conditional probabilities.'),
      S('definition', 'Expectation', { term: 'Expected value E[X]', def: 'The probability-weighted average of all possible values: E[X] = Σ x · P(x). The long-run average.', eg: 'a fair die: (1 + 2 + 3 + 4 + 5 + 6) / 6 = 3.5' }, 'The expected value is the probability weighted average of a random variable, its long run average. For a fair die it is three and a half, even though you can never roll three and a half. Training a model minimises the expected loss over the data distribution.'),
      S('definition', 'Variance', { term: 'Variance and standard deviation', def: 'Var[X] = E[(X − E[X])²]: the average squared distance from the mean. σ = √Var is in the original units.', eg: 'one die roll: σ ≈ 1.71' }, 'Variance measures spread: the average squared distance from the mean. Its square root, the standard deviation, is in the original units. A single die roll has a standard deviation of about one point seven one. High variance means individual outcomes are unpredictable.'),
      S('definition', 'Covariance and correlation', { term: 'Covariance & correlation', def: 'Cov[X, Y] = E[(X − μx)(Y − μy)] measures whether two variables move together. Correlation rescales it to lie between −1 and 1.', eg: 'height and weight are positively correlated · correlation is not causation' }, 'Covariance measures whether two variables move together: positive when they rise and fall together, negative when one rises as the other falls. Correlation rescales covariance to lie between minus one and one. Covariance matrices are exactly what PCA decomposes into eigenvectors.'),
      S('question', 'Pause and think', { q: 'Ice-cream sales and drowning incidents are strongly correlated. Does ice cream cause drowning?', a: 'No. A hidden confounder — hot weather — drives both. Correlation alone never proves causation.' }, 'Pause and think. Across a year, ice cream sales and drowning incidents are strongly correlated. Does eating ice cream cause drowning? Of course not. A hidden common cause, hot weather, drives both. Correlation alone never proves causation, and models that learn correlations can be fooled in the same way.'),
      S('distribution', 'A family of distributions', { mode: 'families' }, 'A handful of distributions cover most of machine learning. The Bernoulli models a single yes or no event. The uniform treats every value in a range equally. The normal, or Gaussian, describes sums of many small effects. The exponential describes waiting times between random events.'),
      S('distribution', 'The binomial', { mode: 'binomial', n: 10, probs: [0.5, 0.2, 0.8] }, 'Repeat a Bernoulli trial n times and count the successes, and you get the binomial distribution. With ten fair coin flips, five heads is most likely. Shift the success probability to point two and the peak moves to two. Its mean is n times p and its variance is n p times one minus p.'),
      S('definition', 'The Poisson distribution', { term: 'Poisson distribution', def: 'Counts of independent events in a fixed interval, with average rate λ. Its mean and variance both equal λ.', eg: 'requests per second to a model server · typos per page · photons per pixel' }, 'Another useful distribution is the Poisson, which counts independent events in a fixed interval, like requests per second arriving at a model server. It has a single parameter, the average rate lambda, which is both its mean and its variance. Engineers use it to plan how many servers to run.'),
      S('distribution', 'The normal distribution', { mode: 'normal', params: [[0, 1], [2, 1], [0, 2], [0, 0.6]] }, 'The normal distribution is the famous bell curve. Its mean, mu, sets the centre, and its standard deviation, sigma, sets the width. Increasing sigma spreads it out and flattens it, because the total area under the curve must always equal one.'),
      S('distribution', 'The 68–95–99.7 rule', { mode: 'rule', ymax: 0.5 }, 'For any normal distribution, about sixty eight percent of values fall within one standard deviation of the mean, ninety five percent within two, and ninety nine point seven percent within three. Values beyond three standard deviations are rare, which makes this a common first rule for spotting outliers.'),
      S('question', 'Pause and think', { q: 'Exam scores are normal with mean 70 and σ = 10. Roughly what fraction scored above 90?', a: 'About 2.5%. 90 is two σ above the mean; 95% lie within ±2σ, leaving 5% in the two tails, half of it above.' }, 'Pause and think. Exam scores are normally distributed with mean seventy and standard deviation ten. Roughly what fraction scored above ninety? Ninety is two standard deviations above the mean. Ninety five percent lie within two standard deviations, so five percent are in the two tails, and half of that, two and a half percent, is above ninety.'),
      S('distribution', 'Sampling', { mode: 'sample', ymax: 0.5 }, 'Now let us draw random samples from a standard normal and build a histogram. With only ten samples the shape is ragged. As the number grows to thousands, the histogram fills in the true curve, and the sample mean and standard deviation settle close to zero and one.'),
      S('definition', 'The law of large numbers', { term: 'Law of large numbers', def: 'As the number of independent samples grows, their average converges to the expected value.', eg: 'why more data gives more reliable estimates of accuracy, averages and gradients' }, 'That settling down is the law of large numbers: the average of many independent samples converges to the expected value. It is why larger test sets give more reliable accuracy estimates, and why averaging gradients over a mini batch gives a useful estimate of the true gradient.'),
      S('clt', 'The central limit theorem', {}, 'The central limit theorem is even more surprising. Roll one die and the results are flat, uniform. Average two dice and a peak appears. Average five, then thirty, and a near perfect bell curve emerges, with a spread that shrinks like one over the square root of the number of dice: from one point seven down to about point three.'),
      S('equation', 'Standard error', { head: 'How precise is an average?', size: 56, parts: [{ t: 'SE', c: 'amber', note: 'Standard error: the spread of the sample average' }, { t: ' = ' }, { t: 'σ', c: 'cyan', note: 'Spread of a single observation' }, { t: ' / √n', c: 'pink', note: 'Shrinks with the square root of the sample size' }], below: 'To halve the uncertainty you need four times as much data' }, 'The spread of an average is called the standard error: sigma divided by the square root of n. This square root has a practical sting. To halve the uncertainty of a measurement, such as a model’s accuracy, you need four times as much data.'),
      S('montecarlo', 'Monte Carlo methods', {}, 'Randomness can also compute things. Scatter random points in a square and count how many land inside the quarter circle. Four times that fraction estimates pi. With three thousand points we get about three point one eight, and the error shrinks like one over the square root of the number of points.'),
      S('definition', 'Monte Carlo in ML', { term: 'Monte Carlo estimation', def: 'Estimate an expectation by averaging over random samples: E[f(X)] ≈ (1/N) Σ f(xᵢ).', eg: 'stochastic gradients, dropout at test time, Bayesian inference and reinforcement learning returns all use it' }, 'This idea, estimating an expectation by averaging random samples, is called Monte Carlo estimation. It is everywhere in machine learning. Stochastic gradient descent estimates the true gradient from a random batch, and reinforcement learning estimates the value of a state by averaging sampled returns.'),
      S('dropout', 'Randomness inside training', {}, 'Probability is not only for describing data; we also inject randomness on purpose. Dropout switches each neuron off with some probability during training, a Bernoulli coin flip per neuron. This stops the network from relying on any single unit and acts as a powerful regulariser.'),
      S('markov', 'Markov chains', {}, 'A Markov chain is a random process where the next state depends only on the current one. In this weather model, a sunny day is followed by sunshine seventy percent of the time. Run it for many steps and the time spent in each state converges to a fixed long run distribution.'),
      S('definition', 'Why Markov chains matter', { term: 'Markov property', def: 'The future depends only on the present state, not on the path that led there.', eg: 'the basis of MCMC sampling, hidden Markov models, PageRank and reinforcement learning (MDPs)' }, 'The key assumption is the Markov property: the future depends only on the present, not on how we got here. It underpins Markov chain Monte Carlo sampling, hidden Markov models for speech, Google’s PageRank, and Markov decision processes, the foundation of reinforcement learning.'),
      S('definition', 'Independence', { term: 'Independence', def: 'X and Y are independent if P(X and Y) = P(X) · P(Y): knowing one tells you nothing about the other.', eg: 'the i.i.d. assumption: training examples independent and identically distributed' }, 'Two events are independent when knowing one tells you nothing about the other, so their joint probability is the product of their separate probabilities. Much of machine learning assumes the data is independent and identically distributed, and many real failures happen when that assumption breaks.'),
      S('sampling', 'Probabilities from a network', { mode: 'temp' }, 'Neural networks produce probabilities with the softmax function, which turns any list of scores into positive numbers that sum to one. A temperature setting sharpens or flattens the distribution, which is exactly how language models control how adventurous their word choices are.'),
      S('code', 'In code', { head: 'Sampling and estimating with NumPy', file: 'probability.py', lines: ['import numpy as np', 'rng = np.random.default_rng(0)', '', 'x = rng.normal(loc=0, scale=1, size=5000)', 'print(x.mean(), x.std())          # close to 0 and 1', 'print(np.mean(np.abs(x) < 1))      # about 0.68', '', 'dice = rng.integers(1, 7, size=(4000, 30)).mean(axis=1)', 'print(dice.mean(), dice.std())     # about 3.5 and 0.31'], hl: [[3, 4], 5, [7, 8]], notes: ['Draw 5,000 samples from a standard normal', 'Check the 68% rule empirically', 'Central limit theorem: averages of 30 dice'] }, 'In code, NumPy’s random generator makes these experiments easy. Draw five thousand normal samples and the mean and standard deviation come out close to zero and one. About sixty eight percent fall within one standard deviation, and averages of thirty dice have a spread of about point three one.'),
      S('bullets', 'Pitfalls', { head: 'Common probability pitfalls', items: ['Base-rate neglect — ignoring how rare a class is', 'Confusing P(A|B) with P(B|A)', 'Assuming independence — when data is correlated or time-ordered', 'Trusting small samples — the standard error is large'] }, 'Beware of common pitfalls. Base rate neglect ignores how rare a class is. Confusing the probability of A given B with B given A is a classic error. Assuming independence fails for time series and grouped data. And small samples have large standard errors, so their averages can mislead.'),
      S('bullets', 'Recap', { style: 'recap', items: ['Probabilities are between 0 and 1 and sum to 1', 'Bayes’ theorem: priors matter — beware base rates', 'Expectation = long-run average; variance = spread', 'Normal: 68–95–99.7 within 1, 2, 3 σ', 'Averages converge (LLN) and become normal (CLT), with error σ/√n'] }, 'To recap. Probabilities lie between zero and one and sum to one. Bayes’ theorem reminds us that priors matter. Expectation is the long run average and variance is the spread. For a normal distribution, sixty eight, ninety five and ninety nine point seven percent lie within one, two and three sigma. And averages converge and become normal.')
    ],
    takeaways: ['Probability quantifies uncertainty; classifiers output conditional probabilities P(label | input).', 'Bayes’ theorem combines a prior with evidence; ignoring base rates misleads.', 'Expectation is the long-run average; variance and standard deviation measure spread.', 'Bernoulli, binomial, normal and exponential distributions cover many ML situations.', 'The law of large numbers and the central limit theorem explain why averages are reliable; the standard error shrinks as σ/√n.', 'Monte Carlo estimation and Markov chains power SGD, sampling methods and reinforcement learning.'],
    quiz: [
      { q: 'What is the expected value of a fair six-sided die?', a: ['3', '3.5', '4', '6'], c: 1, why: '(1+2+3+4+5+6)/6 = 3.5.' },
      { q: 'Roughly what fraction of a normal distribution lies within ±2σ of the mean?', a: ['68%', '95%', '99.7%', '50%'], c: 1, why: 'The 68–95–99.7 rule.' },
      { q: 'How does the standard error of an average scale with sample size n?', a: ['1/n', '1/√n', 'n', 'It does not change'], c: 1, why: 'SE = σ/√n.' },
      { q: 'What does the central limit theorem say?', a: ['All data is normal', 'Averages of many independent samples tend towards a normal distribution', 'Variance always grows', 'Probabilities sum to 2'], c: 1, why: 'Whatever the original shape, averages become bell-shaped.' },
      { q: 'In a Markov chain, the next state depends on…', a: ['The entire history', 'Only the current state', 'Nothing at all', 'The final state'], c: 1, why: 'That is the Markov property.' }
    ],
    read: ['probability-fundamentals', 'random-variables-and-distributions', 'gaussian-distribution-deep-dive', 'sampling-and-monte-carlo-methods', 'markov-chains-for-ml']
  },
  {
    slug: 'statistics-and-information-theory', title: 'Likelihood, Bayes and Information Theory', track: 'math', level: 'Advanced', deep: true,
    summary: 'Why models minimise cross-entropy: maximum likelihood, priors and MAP, Bayesian updating, entropy, cross-entropy and KL divergence — the statistics hiding inside every loss function.',
    scenes: [
      S('title', 'Introduction', { title: 'Likelihood, Bayes and Information Theory', sub: 'The statistics hiding inside every loss function', track: 'Mathematics for ML' }, 'Why do classifiers minimise cross entropy? Why does squared error appear in regression? Why do we add weight decay? The answers come from two beautiful fields: statistical estimation and information theory. This deep dive connects them to the loss functions you use every day.'),
      S('definition', 'Parameters and data', { term: 'Statistical model', def: 'A family of probability distributions p(x | θ), indexed by parameters θ. Learning = choosing θ so the model explains the data well.', eg: 'a Gaussian with θ = (μ, σ); a neural network with θ = millions of weights' }, 'A statistical model is a family of probability distributions controlled by parameters, written p of x given theta. A Gaussian has two parameters, a mean and a standard deviation. A neural network is also a probability model, with millions of parameters. Learning means choosing good values for theta.'),
      S('definition', 'Likelihood', { term: 'Likelihood L(θ)', def: 'How probable the observed data is under parameters θ: L(θ) = Π p(xᵢ | θ) for independent data points.', eg: 'the same formula as probability, but read as a function of θ with the data fixed' }, 'The likelihood asks: if the parameters were theta, how probable would the data we actually observed be? For independent data points it is the product of each point’s probability. It uses the same formula as probability, but we read it as a function of the parameters with the data held fixed.'),
      S('mle', 'Maximum likelihood', {}, 'Maximum likelihood estimation picks the parameters that make the data most probable. Watch the Gaussian slide along. Each bar shows how likely one data point is under the current curve. The log likelihood, on the right, peaks exactly at the sample mean, two point six five. That is the maximum likelihood estimate.'),
      S('equation', 'Why take logs?', { head: 'Log-likelihood', size: 50, parts: [{ t: 'log L(θ)', c: 'amber', note: 'Products of many tiny probabilities underflow to 0 on a computer…' }, { t: ' = ' }, { t: 'Σ', c: 'pink', note: '…but the log turns the product into a sum' }, { t: ' log p(xᵢ | θ)', c: 'cyan', note: 'Each point contributes one term' }], below: 'Same maximiser, better numerics, easy gradients' }, 'In practice we maximise the log likelihood instead. The logarithm turns a product of many tiny probabilities, which would underflow to zero on a computer, into a sum of manageable numbers. Because the log only increases, the best parameters do not change, and sums are easy to differentiate.'),
      S('equation', 'Loss = negative log-likelihood', { head: 'From likelihood to loss', size: 48, parts: [{ t: 'loss', c: 'red', note: 'What training minimises' }, { t: ' = ' }, { t: '− (1/n) Σ log p(yᵢ | xᵢ, θ)', c: 'amber', note: 'The average negative log-likelihood of the correct answers' }], below: 'Gaussian noise → squared error.   Categorical outputs → cross-entropy.' }, 'Flip the sign and average, and you get a loss to minimise: the negative log likelihood. This single idea generates the standard losses. If you assume Gaussian noise around the prediction, it becomes squared error. If the output is a category, it becomes cross entropy.'),
      S('question', 'Pause and think', { q: 'A model assigns probability 0.9 to the correct class for one example and 0.1 for another. What is the negative log-likelihood of each?', a: '−ln 0.9 ≈ 0.11 (small loss) and −ln 0.1 ≈ 2.30 (large loss). Confident mistakes are punished heavily.' }, 'Pause and think. A model assigns probability point nine to the correct class for one example, and only point one for another. What is the loss for each? Minus the log of point nine is about point one one, a small loss. Minus the log of point one is about two point three: confident mistakes are punished heavily.'),
      S('plot', 'The shape of the loss', { head: 'Negative log-likelihood of the correct class', x: [0.02, 1], y: [0, 4], xstep: 0.2, fns: [{ f: '-log(x)', label: '−ln p', lx: 0.2, dx: 12, dy: -10, align: 'left' }], points: [[0.9, 0.105, 'p = 0.9 → 0.11', 'green'], [0.5, 0.693, 'p = 0.5 → 0.69', 'amber'], [0.1, 2.303, 'p = 0.1 → 2.30', 'red']], xl: 'probability given to the correct answer', note: 'Near-certain and right: almost no loss.  Confident and wrong: a huge loss.' }, 'This curve shows the loss for one example as a function of the probability given to the correct answer. At point nine the loss is tiny. At one half it is about point seven. As the probability approaches zero, the loss shoots up towards infinity, so the model is pushed hard never to be confidently wrong.'),
      S('definition', 'Estimators', { term: 'Bias and variance of an estimator', def: 'Bias: does the estimate hit the right value on average? Variance: how much does it wobble from sample to sample?', eg: 'the sample variance divides by n − 1, not n, to remove a small bias' }, 'An estimate computed from data is itself random, because a different sample would give a different answer. Its bias asks whether it is right on average, and its variance asks how much it wobbles. The sample variance divides by n minus one instead of n precisely to remove a small bias.'),
      S('darts', 'Bias and variance', {}, 'The dartboard picture makes this concrete. Low bias and low variance cluster tightly on the bullseye. High bias misses consistently in one direction. High variance scatters widely. The same trade off governs models: simple models tend to be biased, while very flexible ones tend to have high variance.'),
      S('definition', 'Priors', { term: 'Prior p(θ)', def: 'What we believe about the parameters before seeing the data.', eg: '“weights are probably small” is a Gaussian prior centred on zero' }, 'Maximum likelihood listens only to the data, which is risky when data is scarce. Bayesian statistics adds a prior: what we believe about the parameters before seeing any data. For example, believing that weights are probably small corresponds to a Gaussian prior centred on zero.'),
      S('equation', 'Posterior', { head: 'Bayes’ theorem for parameters', size: 52, parts: [{ t: 'p(θ | D)', c: 'green', note: 'Posterior: belief after seeing the data D' }, { t: ' ∝ ' }, { t: 'p(D | θ)', c: 'amber', note: 'Likelihood: how well θ explains the data' }, { t: ' · ' }, { t: 'p(θ)', c: 'cyan', note: 'Prior: belief before the data' }], below: 'posterior ∝ likelihood × prior' }, 'Bayes’ theorem combines the two. The posterior, our belief after seeing the data, is proportional to the likelihood times the prior. With little data the prior dominates. With lots of data the likelihood takes over and the prior washes out.'),
      S('posterior', 'Bayesian updating', {}, 'Here is Bayesian updating with a coin of unknown bias. We start with a gentle prior centred on one half. As flips arrive, the posterior curve shifts and narrows. After forty flips with twenty eight heads, it concentrates near point seven: more data means more confident beliefs.'),
      S('question', 'Pause and think', { q: 'A coin lands heads 7 times in 10 flips. What is the MLE of its bias? With a Beta(2, 2) prior, what is the MAP estimate?', a: 'MLE = 7/10 = 0.70. MAP = (7 + 2 − 1)/(10 + 2 + 2 − 2) = 8/12 ≈ 0.67 — pulled slightly towards 0.5 by the prior.' }, 'Pause and think. A coin lands heads seven times in ten flips. What is the maximum likelihood estimate of its bias? Seven tenths. With a gentle Beta two, two prior, the MAP estimate is eight twelfths, about point six seven, pulled a little towards one half by the prior belief.'),
      S('definition', 'MAP estimation', { term: 'MAP estimate', def: 'Maximum a posteriori: the single most probable θ under the posterior. Loss = −log likelihood − log prior.', eg: 'a Gaussian prior on weights adds λ‖θ‖² to the loss: that is L2 regularisation (weight decay)' }, 'Often we want a single best answer: the peak of the posterior, called the maximum a posteriori, or MAP, estimate. Its loss is the negative log likelihood minus the log prior. With a Gaussian prior on the weights, that extra term is exactly L two regularisation, also known as weight decay.'),
      S('norms', 'Priors as regularisers', { mode: 'reg' }, 'Different priors give different regularisers. A Gaussian prior gives the L two penalty, a circle, which shrinks all weights a little. A Laplace prior gives the L one penalty, a diamond, whose corners push some weights to exactly zero. Here the L one solution lands on a corner: a sparse model.'),
      S('question', 'Pause and think', { q: 'You have 20 training examples and 10,000 features. Should you rely on maximum likelihood alone?', a: 'No. With so little data the MLE will overfit badly. A prior (regularisation) such as L1 or L2 is essential — or collect more data.' }, 'Pause and think. You have twenty training examples and ten thousand features. Should you rely on maximum likelihood alone? No. With so little data, maximum likelihood will happily overfit. A prior, in other words regularisation such as L one or L two, is essential, or better still, collect more data.'),
      S('definition', 'Information', { term: 'Information (surprise)', def: 'An outcome with probability p carries −log₂ p bits of information. Rare events are surprising; certain events carry no information.', eg: 'a fair coin flip: 1 bit · an event with p = 1/8: 3 bits' }, 'Now to information theory, founded by Claude Shannon. The information in an outcome is its surprise: minus the log of its probability. A fair coin flip carries one bit. An event with a one in eight chance carries three bits. Something certain carries no information at all.'),
      S('entropy', 'Entropy', {}, 'Entropy is the average surprise of a distribution. Four equally likely outcomes give the maximum, two bits. As the distribution becomes peaked, entropy falls: one point eight five bits, then one point three six, and finally only about point two four bits when one outcome is almost certain.'),
      S('definition', 'Entropy in ML', { term: 'Entropy H(p)', def: 'H(p) = −Σ p(x) log p(x): the minimum average number of bits needed to encode outcomes drawn from p.', eg: 'decision trees split to reduce entropy (information gain)' }, 'Formally, entropy is minus the sum of p log p. It is the minimum average number of bits needed to encode outcomes from that distribution, which is why it underlies compression. Decision trees use it too: they choose splits that reduce entropy the most, called information gain.'),
      S('tree-split', 'Information gain', {}, 'Here a decision tree splits the data. A good split creates groups that are purer, each dominated by one class, so the entropy after the split is lower. The reduction in entropy is the information gain, and the tree greedily picks the split with the largest gain.'),
      S('entropy', 'Cross-entropy and KL', { mode: 'kl' }, 'Now suppose the truth is P, in blue, but our model predicts Q, in pink. Cross entropy measures the average surprise when outcomes come from P but we encode them using Q. It starts at two point six eight bits, well above the entropy of P, one point six five. The gap is the KL divergence.'),
      S('equation', 'The key identity', { head: 'Cross-entropy = entropy + KL divergence', size: 44, parts: [{ t: 'H(P, Q)', c: 'pink', note: 'Cross-entropy: what the model pays' }, { t: ' = ' }, { t: 'H(P)', c: 'cyan', note: 'Entropy of the truth: fixed, cannot be reduced' }, { t: ' + ' }, { t: 'KL(P ‖ Q)', c: 'amber', note: 'The extra cost of the model being wrong — always ≥ 0' }], below: 'Minimising cross-entropy = minimising KL = making Q match P' }, 'This identity is the punchline. Cross entropy equals the entropy of the truth plus the KL divergence. The entropy of the data is fixed, so minimising cross entropy is exactly minimising the KL divergence, pulling the model’s distribution towards the true one. By the end here it is only point zero one five bits.'),
      S('next-token', 'Cross-entropy in LLMs', {}, 'Language models are trained with exactly this loss. At every position the model predicts a distribution over the next token, and the loss is minus the log probability of the actual next token. Averaged over a sentence, it is the cross entropy, and its exponential is called perplexity.'),
      S('question', 'Pause and think', { q: 'Is KL divergence symmetric — does KL(P‖Q) equal KL(Q‖P)?', a: 'No. KL(P‖Q) heavily penalises Q for missing outcomes P considers likely; the reverse penalises Q for putting mass where P has little. They are generally different.' }, 'Pause and think. Is the KL divergence symmetric? Is KL of P given Q the same as KL of Q given P? No. One direction heavily penalises the model for missing outcomes the truth considers likely, the other penalises it for putting probability where the truth has little. They generally differ.'),
      S('definition', 'Perplexity', { term: 'Perplexity', def: 'exp(cross-entropy): the effective number of equally likely choices the model is torn between at each step.', eg: 'perplexity 10 ≈ as uncertain as picking uniformly among 10 words' }, 'Language model quality is often reported as perplexity, the exponential of the cross entropy. It has a lovely interpretation: the effective number of equally likely words the model is choosing between at each step. A perplexity of ten means the model is as uncertain as if it were picking among ten words.'),
      S('definition', 'Mutual information', { term: 'Mutual information I(X; Y)', def: 'How much knowing X reduces uncertainty about Y: I = H(Y) − H(Y | X). It is zero exactly when X and Y are independent.', eg: 'used for feature selection, and in contrastive objectives such as CLIP' }, 'One more quantity: mutual information, how much knowing one variable reduces our uncertainty about another. It is zero exactly when the two are independent. It is used to rank features, and contrastive methods like CLIP can be understood as maximising a bound on the mutual information between images and captions.'),
      S('table', 'Where KL appears', { head: 'KL divergence across machine learning', cols: ['Where', 'What it does'], widths: [1, 2.4], rows: [['Classification & LLM training', 'cross-entropy loss = KL to the data distribution (plus a constant)'], ['Variational autoencoders', 'KL term keeps each latent code close to a standard normal'], ['RLHF & PPO', 'KL penalty keeps the tuned model close to the reference model'], ['Knowledge distillation', 'student matches the teacher’s full output distribution'], ['Drift monitoring', 'PSI and related scores compare live and training distributions']] }, 'KL divergence appears across machine learning. It is inside every cross entropy loss. It keeps the latent codes of variational autoencoders tidy. It stops models tuned with human feedback from drifting too far from the original. It drives knowledge distillation, and related scores monitor data drift in production.'),
      S('code', 'In code', { head: 'Entropy, cross-entropy and KL in NumPy', file: 'info.py', lines: ['import numpy as np', '', 'P = np.array([0.5, 0.3, 0.15, 0.05])     # truth', 'Q = np.array([0.1, 0.2, 0.3, 0.4])       # model', '', 'H  = -(P * np.log2(P)).sum()             # 1.648 bits', 'CE = -(P * np.log2(Q)).sum()             # 2.684 bits', 'KL = CE - H                              # 1.036 bits', '', 'loss = -np.log(0.9)                      # NLL of one prediction: 0.105'], hl: [[2, 3], [5, 7], 9], notes: ['A true distribution P and a model distribution Q', 'Entropy, cross-entropy and their gap: the KL divergence', 'The per-example loss when the correct class gets 0.9'] }, 'In code, these are one liners. With the truth P and a poor model Q, the entropy is one point six five bits, the cross entropy two point six eight, and the KL divergence, their difference, is about one point zero four bits. Deep learning libraries compute the same thing, usually with natural logs.'),
      S('bullets', 'Putting it together', { head: 'One idea, many losses', items: ['Squared error — negative log-likelihood under Gaussian noise', 'Cross-entropy — negative log-likelihood of categorical labels', 'Weight decay — a Gaussian prior (MAP estimation)', 'L1 penalty — a Laplace prior that encourages sparsity'] }, 'Putting it all together: one idea explains many losses. Squared error is the negative log likelihood under Gaussian noise. Cross entropy is the negative log likelihood of categories. Weight decay is a Gaussian prior, and the L one penalty is a Laplace prior that encourages sparsity.'),
      S('bullets', 'Recap', { style: 'recap', items: ['MLE picks θ that makes the observed data most probable', 'Minimising negative log-likelihood = the standard losses', 'Priors + likelihood → posterior; MAP adds regularisation', 'Entropy = average surprise; cross-entropy = entropy + KL', 'Training a classifier minimises KL to the data distribution'] }, 'To recap. Maximum likelihood picks the parameters that make the observed data most probable, and minimising negative log likelihood gives the standard losses. Priors combine with the likelihood into a posterior, and MAP estimation adds regularisation. Entropy is average surprise, and cross entropy is entropy plus KL divergence.')
    ],
    takeaways: ['The likelihood is the probability of the observed data as a function of the parameters.', 'Maximum likelihood estimation maximises Σ log p(xᵢ | θ); for a Gaussian mean it gives the sample mean.', 'Negative log-likelihood yields squared error (Gaussian noise) and cross-entropy (categorical outputs).', 'Posterior ∝ likelihood × prior; MAP with a Gaussian prior equals L2 regularisation.', 'Entropy is the average surprise −Σ p log p; cross-entropy = entropy + KL divergence.', 'KL divergence is asymmetric and appears in VAEs, RLHF, distillation and drift monitoring.'],
    quiz: [
      { q: 'Maximum likelihood estimation chooses parameters that…', a: ['Minimise the number of parameters', 'Make the observed data most probable', 'Maximise the prior', 'Make the loss negative'], c: 1, why: 'That is the definition of MLE.' },
      { q: 'Minimising squared error corresponds to MLE under which noise assumption?', a: ['Uniform', 'Gaussian', 'Bernoulli', 'Exponential'], c: 1, why: 'The Gaussian log-density contains −(y − ŷ)².' },
      { q: 'What is the entropy of a fair coin flip?', a: ['0 bits', '0.5 bits', '1 bit', '2 bits'], c: 2, why: '−2 × 0.5 log₂ 0.5 = 1.' },
      { q: 'Cross-entropy H(P, Q) equals…', a: ['H(P) − KL(P‖Q)', 'H(P) + KL(P‖Q)', 'KL(Q‖P)', 'H(Q)'], c: 1, why: 'The key identity of this lecture.' },
      { q: 'A Gaussian prior on the weights, in MAP estimation, is equivalent to…', a: ['Dropout', 'L2 regularisation (weight decay)', 'Early stopping', 'Data augmentation'], c: 1, why: '−log of a Gaussian prior is a squared-norm penalty.' }
    ],
    read: ['maximum-likelihood-estimation', 'map-estimation-and-priors', 'information-theory-entropy-kl', 'bayes-theorem-explained']
  }
];
